            [
                ExpressionLogic.Literal(ExpressionLogic.NumberLiteral 10.0)
                ExpressionLogic.Hole
            ]
        )

    assertEqual
        (portableOf partialExpression
         |> Result.map (fun text -> text.Contains("\"tag\": \"partial\"")))
        (Ok true)
        "the partial portable document keeps its tag"

    (match parseProse "subtract <| 10." with
     | Ok expression ->
         assertEqual
             (ExpressionLogic.ReversePipeline(
                 ExpressionLogic.Word "subtract",
                 ExpressionLogic.Literal(ExpressionLogic.NumberLiteral 10.0)
             ))
             expression
             "the reverse pipe parses to a reverse-pipeline expression"
     | Error error -> assertEqual true false ("the reverse pipe should parse: " + ProseParser.describeError error))

    (match parseProse "f <| g <| 5." with
     | Ok expression ->
         assertEqual
             (ExpressionLogic.ReversePipeline(
                 ExpressionLogic.Word "f",
                 ExpressionLogic.ReversePipeline(
                     ExpressionLogic.Word "g",
                     ExpressionLogic.Literal(ExpressionLogic.NumberLiteral 5.0)
                 )
             ))
             expression
             "the reverse pipe is right-associative"
     | Error error ->
         assertEqual true false ("the chained reverse pipe should parse: " + ProseParser.describeError error))

    assertEqual (Ok 5.0) (runProse "subtract(10 _) <| 5.") "the reverse pipe fills a partial hole"

    let pipelineDocument = portableOf pipelineExpression

    let desugaredDocument =
        portableOf (ExpressionLogic.desugarPipeline pipelineExpression)

    assertEqual
        false
        (pipelineDocument = desugaredDocument)
        "the pipeline portable document is distinct from its desugared call"

    let proseErrorName (text: string) : string =
        match parseProse text with
        | Ok _ -> "parsed"
        | Error(ProseParser.ExpectedMatch _) -> "ExpectedMatch"
        | Error(ProseParser.EmptyMatch _) -> "EmptyMatch"
        | Error(ProseParser.EmptyProgram _) -> "EmptyProgram"
        | Error(ProseParser.ExpectedClause _) -> "ExpectedClause"
        | Error(ProseParser.ExpectedThen _) -> "ExpectedThen"
        | Error(ProseParser.ExpectedPeriod _) -> "ExpectedPeriod"
        | Error(ProseParser.DuplicateOtherwise _) -> "DuplicateOtherwise"
        | Error(ProseParser.ClauseAfterOtherwise _) -> "ClauseAfterOtherwise"
        | Error(ProseParser.ExpectedMatchSeparator _) -> "ExpectedMatchSeparator"
        | Error(ProseParser.ExpectedClose _) -> "ExpectedClose"
        | Error(ProseParser.UnexpectedClose _) -> "UnexpectedClose"
        | Error(ProseParser.UnexpectedComma _) -> "UnexpectedComma"
        | Error(ProseParser.UnclosedParenthesis _) -> "UnclosedParenthesis"
        | Error(ProseParser.UnexpectedClosingParenthesis _) -> "UnexpectedClosingParenthesis"
        | Error(ProseParser.ExpectedExpression _) -> "ExpectedExpression"
        | Error(ProseParser.ExpectedPattern _) -> "ExpectedPattern"
        | Error(ProseParser.ExpectedSortName _) -> "ExpectedSortName"
        | Error(ProseParser.ExpectedEquals _) -> "ExpectedEquals"
        | Error(ProseParser.ExpectedBindingName _) -> "ExpectedBindingName"
        | Error(ProseParser.UppercaseName _) -> "UppercaseName"
        | Error(ProseParser.UnclosedText _) -> "UnclosedText"
        | Error(ProseParser.UnexpectedEnd _) -> "UnexpectedEnd"
        | Error(ProseParser.UnexpectedToken _) -> "UnexpectedToken"
        | Error(ProseParser.LogicOutsideBook _) -> "LogicOutsideBook"
        | Error(ProseParser.UnexpectedSentence _) -> "UnexpectedSentence"
        | Error(ProseParser.EmptyBook _) -> "EmptyBook"

    assertEqual "UppercaseName" (proseErrorName "Match 5.\notherwise 0.") "keywords and names are lowercase"



    assertEqual "ExpectedMatch" (proseErrorName "value.\notherwise 0.") "a program starts with match"

    assertEqual "ExpectedMatch" (proseErrorName "when 1 then 1.") "a clause needs a match"

    assertEqual "EmptyProgram" (proseErrorName "") "a program needs a sentence"

    assertEqual "ExpectedThen" (proseErrorName "match 5.\nwhen 1 \"one\".") "a when clause needs then"

    assertEqual "EmptyMatch" (proseErrorName "match 5.") "a match needs a choice"

    assertEqual "DuplicateOtherwise" (proseErrorName "match 5.\notherwise 0.\notherwise 1.") "a match has one otherwise"

    assertEqual "ClauseAfterOtherwise" (proseErrorName "match 5.\notherwise 0.\nwhen 1 then 1.") "otherwise is last"

    assertEqual
        "UnclosedParenthesis"
        (proseErrorName "match value.\nwhen some(x")
        "a constructor needs its closing parenthesis"

    assertEqual "ExpectedPeriod" (proseErrorName "match 5.\notherwise 0") "a sentence ends with a full stop"

    assertEqual
        "UnexpectedComma"
        (proseErrorName "match value.\nwhen some(x) then is alive(x, y).")
        "a comma outside the choice positions is refused"

    assertEqual "UnexpectedComma" (proseErrorName "match 5, when 1 then 1,.") "a trailing choice comma is refused"

    assertEqual
        "ExpectedMatchSeparator"
        (proseErrorName "match 5 when 1 then 1.")
        "a match head needs a full stop or a comma"

    assertEqual
        "ClauseAfterOtherwise"
        (proseErrorName "match 5, otherwise 0, when 1 then 1.")
        "an inline choice after otherwise is refused"

    assertEqual
        "ExpectedClose"
        (proseErrorName "match x, when 0 then match y, when 1 then 1.")
        "a nested match needs close"

    assertEqual
        "UnexpectedClose"
        (proseErrorName "match x, when 0 then 1 close, otherwise 0.")
        "a close needs a nested match"

    assertEqual "UnclosedText" (proseErrorName "match 0, otherwise \"not found.") "a text literal is closed"

    assertEqual "UnexpectedToken" (proseErrorName "match player-state, otherwise 0.") "a hyphen is not part of a name"

    printfn "Prose shell (D183):"

    match ProseParser.parseProgram [] "run(\"echo\" \"hello\")." with
    | Ok expression ->
        match EvaluatorLowering.lowerExpression expression with
        | Ok program ->
            assertEqual
                [
                    LoweredInstructions.LiteralText "echo"
                    LoweredInstructions.LiteralText "hello"
                    LoweredInstructions.CallWord("$shell.run#2", None)
                ]
                program.Instructions
                "a shell call lowers to a host word carrying its arity"
        | Error refusal ->
            assertEqual
                "ok"
                (EvaluatorLowering.describeRefusal refusal)
                "a shell call lowers to a host word carrying its arity"
    | Error error -> assertEqual "ok" (ProseParser.describeError error) "a shell call parses"

    match ProseParser.parseProgram [] "capture(\"echo\" \"hello\")." with
    | Ok expression ->
        match EvaluatorLowering.lowerExpression expression with
        | Ok program ->
            assertEqual
                [
                    LoweredInstructions.LiteralText "echo"
                    LoweredInstructions.LiteralText "hello"
                    LoweredInstructions.CallWord("$shell.capture#2", None)
                ]
                program.Instructions
                "a capture call lowers to its own host word"
        | Error refusal ->
            assertEqual "ok" (EvaluatorLowering.describeRefusal refusal) "a capture call lowers to its own host word"
    | Error error -> assertEqual "ok" (ProseParser.describeError error) "a capture call parses"

    let withRunExpression =
        match ProseParser.parseProgram [] "run \"echo\" with \"hello\"." with
        | Ok expression -> Ok expression
        | Error error -> Error(ProseParser.describeError error)

    (match withRunExpression, ProseParser.parseProgram [] "run(\"echo\" \"hello\")." with
     | Ok withExpression, Ok callExpression ->
         assertEqual callExpression withExpression "the with spelling parses to the call form"
     | Error reason, _ -> assertEqual "ok" reason "the with spelling parses to the call form"
     | _, Error error -> assertEqual "ok" (ProseParser.describeError error) "the with spelling parses to the call form")

    (match withRunExpression with
     | Ok expression ->
         match EvaluatorLowering.lowerExpression expression with
         | Ok program ->
             assertEqual
                 [
                     LoweredInstructions.LiteralText "echo"
                     LoweredInstructions.LiteralText "hello"
                     LoweredInstructions.CallWord("$shell.run#2", None)
                 ]
                 program.Instructions
                 "the with spelling lowers to the same host word"
         | Error refusal ->
             assertEqual
                 "ok"
                 (EvaluatorLowering.describeRefusal refusal)
                 "the with spelling lowers to the same host word"
     | Error reason -> assertEqual "ok" reason "the with spelling lowers to the same host word")

    (match
        ProseShell.runText (ShellHost.ProcessShell() :> ShellHost.ShellProcess) "capture \"echo\" with \"hello\"."
     with
     | ProseShell.ProseCompleted(ProseShell.ProseText text, status) ->
         assertEqual ("hello\n", 0) (text, status) "the with spelling captures output"
     | outcome -> assertEqual "completed text" (showValue (box outcome)) "the with spelling captures output")

    let (shellVocabularyRoot, shellStore0) =
        VocabularyInImage.addVocabulary Vocabulary.gameVocabulary Store.empty

    let shellStore = Store.setVocabularyTable shellVocabularyRoot shellStore0
    let shellState0 = Evaluator.initial shellStore shellVocabularyRoot

    let mutable runCalls: (string * string list) list = []
    let mutable captureCalls: (string * string list) list = []

    let fakeShell =
        { new ShellHost.ShellProcess with
            member _.Run(program, arguments) =
                runCalls <- runCalls @ [ (program, arguments) ]
                Ok 7

            member _.Capture(program, arguments) =
                captureCalls <- captureCalls @ [ (program, arguments) ]
                Ok(0, "hello\n")

            member _.Stream(program, arguments, input) =
                captureCalls <- captureCalls @ [ (program, arguments) ]
                Ok(0, input)

            member _.CheckWritePath(_) = Ok()
        }

    let shellAdapter = ShellHost.wordAdapter fakeShell

    let runState =
        Evaluator.runOrFail
            { shellState0 with
                HostWords = [ shellAdapter ]
                Capabilities = Set.ofList [ "shell" ]
                Program = EvaluatorProgram.ofTokensOrFail [ "\"echo\""; "\"hello\""; "$shell.run#2" ]
            }

    assertEqual [ ("echo", [ "hello" ]) ] runCalls "run passes the program and arguments to the host"
    assertEqual (Some 7) runState.LastCommandStatus "run records the last command status"

    match Stack.popResolved runState.Store runState.Stack with
    | Some(tensor, _) -> assertEqual 7.0 (Tensor.item tensor 0) "run pushes the exit status"
    | None -> assertEqual true false "run pushes the exit status"

    let captureState =
        Evaluator.runOrFail
            { shellState0 with
                HostWords = [ shellAdapter ]
                Capabilities = Set.ofList [ "shell" ]
                Program = EvaluatorProgram.ofTokensOrFail [ "\"echo\""; "\"hello\""; "$shell.capture#2" ]
            }

    assertEqual [ ("echo", [ "hello" ]) ] captureCalls "capture passes the program and arguments to the host"
    assertEqual (Some 0) captureState.LastCommandStatus "capture records the last command status"

    (match Stack.popIndex captureState.Stack with
     | Some(identity, _) ->
         assertEqual
             (Some "hello\n")
             (Store.readTextAt identity captureState.Store)
             "capture pushes standard output as text"
     | None -> assertEqual true false "capture pushes standard output as text")

    (match
        Evaluator.run
            { shellState0 with
                HostWords = [ shellAdapter ]
                Capabilities = Set.ofList [ "shell" ]
                Program = EvaluatorProgram.ofTokensOrFail [ "1"; "\"hello\""; "$shell.run#2" ]
            }
     with
     | Error diagnostic ->
         match diagnostic.Error with
         | HostFailure _ -> assertEqual true true "a non-text argument is a named host refusal"
         | _ -> assertEqual true false "a non-text argument is a named host refusal"
     | Ok _ -> assertEqual true false "a non-text argument is a named host refusal")

    (match
        Evaluator.run
            { shellState0 with
                Program = EvaluatorProgram.ofTokensOrFail [ "\"echo\""; "$shell.run#1" ]
            }
     with
     | Error diagnostic ->
         match diagnostic.Error with
         | HostFailure _ -> assertEqual true true "an unattached host refuses a host word"
         | _ -> assertEqual true false "an unattached host refuses a host word"
     | Ok _ -> assertEqual true false "an unattached host refuses a host word")

    let processShell = ShellHost.ProcessShell() :> ShellHost.ShellProcess

    (match
        Evaluator.run
            { shellState0 with
                HostWords = [ ShellHost.wordAdapter processShell ]
                Capabilities = Set.empty
                Program = EvaluatorProgram.ofTokensOrFail [ "\"echo\""; "$shell.run#1" ]
            }
     with
     | Error diagnostic ->
         match diagnostic.Error with
         | HostFailure _ -> assertEqual true true "a host word needs a granted capability"
         | _ -> assertEqual true false "a host word needs a granted capability"
     | Ok _ -> assertEqual true false "a host word needs a granted capability")

    (match processShell.Capture("/bin/echo", [ "hello" ]) with
     | Ok(status, output) -> assertEqual (0, "hello\n") (status, output) "the process host captures echo output"
     | Error reason -> assertEqual "ok" reason "the process host captures echo output")

    (match processShell.Run("/bin/false", []) with
     | Ok status -> assertEqual 1 status "the process host reports a non-zero status"
     | Error reason -> assertEqual "ok" reason "the process host reports a non-zero status")

    (match processShell.Capture("/bin/echo", [ "a b" ]) with
     | Ok(_, output) -> assertEqual "a b\n" output "a spaced argument is one argument"
     | Error reason -> assertEqual "ok" reason "a spaced argument is one argument")

    (match processShell.Capture("/bin/echo", [ "a; echo b" ]) with
     | Ok(_, output) -> assertEqual "a; echo b\n" output "no shell metacharacter is interpreted"
     | Error reason -> assertEqual "ok" reason "no shell metacharacter is interpreted")

    (match processShell.Capture("/definitely/not/a/program", []) with
     | Error _ -> assertEqual true true "a missing program is a refusal"
     | Ok _ -> assertEqual true false "a missing program is a refusal")

    (match processShell.Capture("/bin/pwd", []) with
     | Ok(_, output) ->
         assertEqual
             (System.IO.Directory.GetCurrentDirectory() + "\n")
