             "the process host inherits the working directory"
     | Error reason -> assertEqual "ok" reason "the process host inherits the working directory")

    let environmentName = "SCALE_SHELL_TEST"
    let previousEnvironment = Environment.GetEnvironmentVariable environmentName
    Environment.SetEnvironmentVariable(environmentName, "inherited")

    (match processShell.Capture("/usr/bin/env", []) with
     | Ok(_, output) ->
         assertEqual true (output.Contains(environmentName + "=inherited")) "the process host inherits the environment"
     | Error reason -> assertEqual "ok" reason "the process host inherits the environment")

    Environment.SetEnvironmentVariable(environmentName, previousEnvironment)

    let scriptPath =
        System.IO.Path.Combine(
            System.IO.Path.GetTempPath(),
            "scale-shell-" + System.Guid.NewGuid().ToString("N") + ".prose"
        )

