     | outcome ->
         assertEqual "completed number" (showValue (box outcome)) "the script runner returns the last command status")

    System.IO.File.Delete failingScriptPath

    (match ProseShell.runTextWith [ ShellHost.wordAdapter processShell ] None "capture echo with hello." with
     | ProseShell.ProseCompleted(ProseShell.ProseText text, status) ->
         assertEqual ("hello\n", 0) (text, status) "a command accepts bare text words"
     | outcome -> assertEqual "completed text" (showValue (box outcome)) "a command accepts bare text words")

    (match ProseShell.runTextWith [ ShellHost.wordAdapter processShell ] None "capture echo with hello. feed cat." with
     | ProseShell.ProseCompleted(ProseShell.ProseText text, status) ->
         assertEqual ("hello\n", 0) (text, status) "feed pipes text into the next command"
     | outcome -> assertEqual "completed text" (showValue (box outcome)) "feed pipes text into the next command")

    let savedDirectory =
        System.IO.Path.Combine(System.IO.Path.GetTempPath(), "scale-save-" + System.Guid.NewGuid().ToString("N"))

    System.IO.Directory.CreateDirectory savedDirectory |> ignore
    let savedName = "savedstage2"

    (match
        ProseShell.runTextWith
            [ ShellHost.wordAdapter processShell ]
            (Some savedDirectory)
            ("capture echo with hello. save " + savedName + ".")
     with
     | ProseShell.ProseCompleted(_, 0) ->
         assertEqual
             "hello\n"
             (System.IO.File.ReadAllText(System.IO.Path.Combine(savedDirectory, savedName)))
             "save writes piped text to a file"
     | outcome -> assertEqual "completed text" (showValue (box outcome)) "save writes piped text to a file")

    System.IO.Directory.Delete(savedDirectory, true)

    let sandboxRoot =
        System.IO.Path.Combine(System.IO.Path.GetTempPath(), "scale-sandbox-" + System.Guid.NewGuid().ToString("N"))

    System.IO.Directory.CreateDirectory sandboxRoot |> ignore

    let sandbox =
        ShellHost.ProcessShell(ShellHost.Restricted(Set.ofList [ "/bin/echo" ], [ sandboxRoot ], true))
        :> ShellHost.ShellProcess

    (match sandbox.Capture("/bin/echo", [ "hello" ]) with
     | Ok _ -> assertEqual true true "a sandbox permits an allowed program"
     | Error reason -> assertEqual "ok" reason "a sandbox permits an allowed program")

    (match sandbox.Capture("/bin/cat", []) with
     | Error reason -> assertEqual true (reason.Contains "does not allow program") "a sandbox refuses a denied program"
     | Ok _ -> assertEqual true false "a sandbox refuses a denied program")

    (match sandbox.CheckWritePath(System.IO.Path.Combine(sandboxRoot, "file.txt")) with
     | Ok() -> assertEqual true true "a sandbox permits a write inside its root"
     | Error reason -> assertEqual "ok" reason "a sandbox permits a write inside its root")

    System.IO.Directory.Delete(sandboxRoot, true)

    printfn "Callable contract (D189):"

    let (leftId, leftStore) = Store.addTensor (Tensor.scalar 3.0) shellState0.Store
    let (rightId, rightStore) = Store.addTensor (Tensor.scalar 4.0) leftStore

    let wordCallState =
        { shellState0 with
            Store = rightStore
            Stack = [ rightId; leftId ]
        }

    (match EvaluatorKernelBridge.executeWord "add" (EvaluatorKernelBridge.toKernel wordCallState) with
     | Ok kernel ->
         let final = EvaluatorKernelBridge.fromKernel kernel

         match Stack.popResolved final.Store final.Stack with
         | Some(tensor, _) -> assertEqual 7.0 (Tensor.item tensor 0) "the lowered path still executes a word"
         | None -> assertEqual true false "the lowered path still executes a word"
     | Error reason -> assertEqual "ok" reason "the lowered path still executes a word")

    let (valueId, valueStore) = Store.addTensor (Tensor.scalar 2.0) shellState0.Store
    let (nameId, nameStore) = Store.addText "x" valueStore

    let bindingState =
        { shellState0 with
            Store = nameStore
            Stack = [ nameId; valueId ]
        }

    (match Evaluator.executeWord "let" bindingState with
     | Error error -> assertEqual "ok" (describeError error) "the lowered path refuses a dynamic lexical binding"
     | Ok bound ->
         match EvaluatorKernelBridge.executeWord "x" (EvaluatorKernelBridge.toKernel bound) with
         | Error reason ->
             assertEqual
                 true
                 (reason.Contains "runtime lexical binding")
                 "the lowered path refuses a dynamic lexical binding"
         | Ok _ -> assertEqual true false "the lowered path refuses a dynamic lexical binding")

    printfn "Books and spells (D184):"

    let bookVocabulary =
        match VocabularyInImage.readVocabulary (Some shellVocabularyRoot) shellStore with
        | Ok vocabulary -> vocabulary
        | Error message -> failwith message

    let bookText = "logic double x = multiply(x 2)."

    let mathBookPath =
        System.IO.Path.Combine(
            System.IO.Path.GetTempPath(),
            "scale-book-" + System.Guid.NewGuid().ToString("N") + ".book"
        )

    System.IO.File.WriteAllText(mathBookPath, bookText)

    (match ProseParser.parseBook bookVocabulary bookText with
     | Ok document ->
         assertEqual 1 (List.length document.Definitions) "a book parses definitions without a trailing sentence"

         assertEqual "double" document.Definitions.Head.Name "a book definition keeps its name"
     | Error error ->
         assertEqual "ok" (ProseParser.describeError error) "a book parses definitions without a trailing sentence")

    (match ProseParser.parseBook bookVocabulary "open math\nlogic main = 1." with
     | Ok document -> assertEqual [ "math" ] document.Opens "a book parses leading opens"
     | Error error -> assertEqual "ok" (ProseParser.describeError error) "a book parses leading opens")

    (match ProseParser.parseBook bookVocabulary "logic main = 1.\nopen math" with
     | Error(ProseParser.OpenAfterDefinition _) -> assertEqual true true "an include after a definition is refused"
     | _ -> assertEqual true false "an include after a definition is refused")

    (match BookRunner.load shellState0 mathBookPath with
     | Ok book ->
         let kind =
             match BookRunner.classify book with
             | BookRunner.Book -> "book"
             | BookRunner.Spell -> "spell"

         assertEqual "book" kind "a book without main is a library"
         assertEqual [ "double" ] (BookRunner.exports book) "a book exports its definitions"
     | Error reason -> assertEqual "ok" reason "a book without main is a library")

    let spellPath =
        System.IO.Path.Combine(
            System.IO.Path.GetTempPath(),
            "scale-spell-" + System.Guid.NewGuid().ToString("N") + ".book"
        )

    System.IO.File.WriteAllText(spellPath, "logic main = 42.")

    (match BookRunner.load shellState0 spellPath with
     | Ok book ->
         let kind =
             match BookRunner.classify book with
             | BookRunner.Book -> "book"
             | BookRunner.Spell -> "spell"

         assertEqual "spell" kind "a book with main is a spell"
     | Error reason -> assertEqual "ok" reason "a book with main is a spell")

    (match ProseParser.parseBook bookVocabulary "add(1 2)." with
     | Error(ProseParser.UnexpectedSentence _) -> assertEqual true true "a free sentence is refused in a book"
     | Error error ->
         assertEqual "UnexpectedSentence" (ProseParser.describeError error) "a free sentence is refused in a book"
     | Ok _ -> assertEqual true false "a free sentence is refused in a book")

    (match ProseParser.parseBook bookVocabulary "logic x 2." with
     | Error(ProseParser.ExpectedEquals _) -> assertEqual true true "a book definition needs ="
     | Error error -> assertEqual "ExpectedEquals" (ProseParser.describeError error) "a book definition needs ="
     | Ok _ -> assertEqual true false "a book definition needs =")

    (match ProseParser.parseProgram [] "cast(\"math.book\" \"double\" 21)." with
     | Ok expression ->
         match EvaluatorLowering.lowerExpression expression with
         | Ok program ->
             assertEqual
                 [
                     LoweredInstructions.LiteralText "math.book"
                     LoweredInstructions.LiteralText "double"
                     LoweredInstructions.LiteralNumber 21.0
                     LoweredInstructions.CallWord("$book.cast#3", None)
                 ]
                 program.Instructions
                 "a prose cast lowers to a book host word"
         | Error refusal ->
             assertEqual "ok" (EvaluatorLowering.describeRefusal refusal) "a prose cast lowers to a book host word"
     | Error error -> assertEqual "ok" (ProseParser.describeError error) "a prose cast lowers to a book host word")

    let argumentState, argumentIds =
        BookRunner.withArguments shellState0 [ "21"; "hello" ]

    (match argumentIds with
     | [ numberId; textId ] ->
         let numeric =
             match Store.lookupTensor numberId argumentState.Store with
             | Some tensor -> Some(Tensor.item tensor 0)
             | None -> None

         assertEqual
             (Some 21.0, Some "hello")
             (numeric, Store.readTextAt textId argumentState.Store)
             "the CLI parses numeric arguments and keeps text"
     | _ -> assertEqual true false "the CLI parses numeric arguments and keeps text")

    let castState =
        { shellState0 with
            HostWords = [ BookHost.wordAdapter ]
            Capabilities = Set.ofList [ "book" ]
            BookBaseDirectory = Some(System.IO.Path.GetDirectoryName mathBookPath)
            Program = EvaluatorProgram.ofTokensOrFail [ "\"" + mathBookPath + "\""; "\"double\""; "21"; "$book.cast#3" ]
        }

    let castFinal = Evaluator.runOrFail castState

    (match Stack.popResolved castFinal.Store castFinal.Stack with
     | Some(tensor, _) -> assertEqual 42.0 (Tensor.item tensor 0) "a prose cast calls a book word"
     | None -> assertEqual true false "a prose cast calls a book word")

    let nestedBookPath =
        System.IO.Path.Combine(
            System.IO.Path.GetTempPath(),
            "scale-book-" + System.Guid.NewGuid().ToString("N") + ".book"
        )

    System.IO.File.WriteAllText(nestedBookPath, "logic double x = multiply(x 2).\nlogic quad x = double(x).")

    (match
        ProseShell.runTextWith
            [ BookHost.wordAdapter ]
            (Some(System.IO.Path.GetDirectoryName nestedBookPath))
            ("cast(\"" + nestedBookPath + "\" \"quad\" 21).")
     with
     | ProseShell.ProseCompleted(ProseShell.ProseNumber number, status) ->
         assertEqual (42.0, 0) (number, status) "a book word can call another book word"
     | outcome -> assertEqual "completed number" (showValue (box outcome)) "a book word can call another book word")

    System.IO.File.Delete nestedBookPath

    let recursiveBooks =
        [
            "cycle loop x = loop(x).\n"
            "logic first x = second(x).\nlogic second x = multiply(x 2).\n"
            "cycle even n = odd(n).\nand odd n = even(n).\n"
        ]

    for text in recursiveBooks do
        let path =
            System.IO.Path.Combine(
                System.IO.Path.GetTempPath(),
                "scale-recursive-" + System.Guid.NewGuid().ToString("N") + ".book"
            )

        System.IO.File.WriteAllText(path, text)

        (match BookRunner.load shellState0 path with
         | Error reason -> assertEqual "ok" reason "a recursive book loads"
         | Ok _ -> assertEqual true true "a recursive book loads")

        System.IO.File.Delete path

    let forwardPath =
        System.IO.Path.Combine(
            System.IO.Path.GetTempPath(),
            "scale-forward-" + System.Guid.NewGuid().ToString("N") + ".book"
        )

    System.IO.File.WriteAllText(forwardPath, "logic first x = second(x).\nlogic second x = multiply(x 2).\n")

    let forwardState, forwardArguments = BookRunner.withArguments shellState0 [ "21" ]

    (match BookRunner.cast forwardState forwardPath (Some "first") forwardArguments with
     | Ok final ->
         match Stack.popResolved final.Store final.Stack with
         | Some(tensor, _) -> assertEqual 42.0 (Tensor.item tensor 0) "a forward book call runs"
         | None -> assertEqual true false "a forward book call runs"
     | Error reason -> assertEqual "ok" reason "a forward book call runs")

    System.IO.File.Delete forwardPath

    let loopPath =
        System.IO.Path.Combine(
            System.IO.Path.GetTempPath(),
            "scale-loop-" + System.Guid.NewGuid().ToString("N") + ".book"
        )

    System.IO.File.WriteAllText(loopPath, "cycle loop x = loop(x).\n")
    let loopState, loopArguments = BookRunner.withArguments shellState0 [ "21" ]

    (match BookRunner.cast loopState loopPath (Some "loop") loopArguments with
     | Error reason -> assertEqual true (reason.Contains "call depth exceeded") "book recursion is depth-bounded"
     | Ok _ -> assertEqual true false "book recursion is depth-bounded")

    System.IO.File.Delete loopPath

    let markerPath (text: string) =
        let path =
            System.IO.Path.Combine(
                System.IO.Path.GetTempPath(),
                "scale-marker-" + System.Guid.NewGuid().ToString("N") + ".book"
            )

        System.IO.File.WriteAllText(path, text)
        path

    let recursiveMarkerPath = markerPath "cycle loop x = loop(x).\n"

    (match BookRunner.load shellState0 recursiveMarkerPath with
     | Ok _ -> assertEqual true true "a cycle marker is accepted"
     | Error reason -> assertEqual "ok" reason "a cycle marker is accepted")

    System.IO.File.Delete recursiveMarkerPath

    let plainMarkerPath = markerPath "logic answer = 42.\n"

    (match BookRunner.load shellState0 plainMarkerPath with
     | Ok _ -> assertEqual true true "a logic marker is accepted without a book call"
     | Error reason -> assertEqual "ok" reason "a logic marker is accepted without a book call")

    System.IO.File.Delete plainMarkerPath

    let inconsistentMarkerPath =
        markerPath "logic first x = first(x).\nlogic second x = multiply(x 2).\n"

    (match BookRunner.load shellState0 inconsistentMarkerPath with
     | Error reason ->
         assertEqual
             true
             (reason.Contains "marked logic but calls itself")
             "a logic marker that calls itself is refused"
     | Ok _ -> assertEqual true false "a logic marker that calls itself is refused")

    System.IO.File.Delete inconsistentMarkerPath

    let falseRecursiveMarkerPath = markerPath "cycle answer = 42.\n"

    (match BookRunner.load shellState0 falseRecursiveMarkerPath with
     | Error reason ->
         assertEqual
             true
             (reason.Contains "marked cycle but calls no book word")
             "a cycle marker without a book call is refused"
     | Ok _ -> assertEqual true false "a cycle marker without a book call is refused")

    System.IO.File.Delete falseRecursiveMarkerPath

    let contractPath =
        markerPath "logic double x = multiply(x 2).\nlogic quad x = double(x).\n"

    (match BookRunner.load shellState0 contractPath with
     | Ok book ->
         let doubleUnit = book.Package.Units |> List.find (fun unit -> unit.Name = "double")
         let quadUnit = book.Package.Units |> List.find (fun unit -> unit.Name = "quad")
         assertEqual false (doubleUnit.SourceHash = quadUnit.SourceHash) "book units carry their own source hashes"
         assertEqual [ "double" ] quadUnit.Dependencies "a book unit records its book dependencies"
     | Error reason -> assertEqual "ok" reason "book units carry their own source hashes")

    System.IO.File.Delete contractPath

    let arityPath = markerPath "logic main x = x.\n"

    (match BookRunner.runSpell shellState0 arityPath with
     | Error reason -> assertEqual true (reason.Contains "main expects 1") "a spell main must take no arguments"
     | Ok _ -> assertEqual true false "a spell main must take no arguments")

    System.IO.File.Delete arityPath

    let lazyPath = markerPath "logic good = 42.\nlogic bad = missing.\n"

    (match BookRunner.cast shellState0 lazyPath (Some "good") [] with
     | Ok final ->
         match Stack.popResolved final.Store final.Stack with
         | Some(tensor, _) -> assertEqual 42.0 (Tensor.item tensor 0) "a book definition is evaluated only when called"
         | None -> assertEqual true false "a book definition is evaluated only when called"
     | Error reason -> assertEqual "ok" reason "a book definition is evaluated only when called")

    System.IO.File.Delete lazyPath

    let wrongArityPath = markerPath "logic pair x y = x.\n"

    (match BookRunner.cast shellState0 wrongArityPath (Some "pair") [] with
     | Error reason -> assertEqual true (reason.Contains "expects 2") "a book call checks the definition arity"
     | Ok _ -> assertEqual true false "a book call checks the definition arity")

    System.IO.File.Delete wrongArityPath

    printfn "Nominal constructors (shape):"

    (match ProseParser.parseBook bookVocabulary "shape point with x y.\nlogic main = 1." with
     | Ok document ->
         assertEqual 1 document.Shapes.Length "a book parses a shape declaration"
         assertEqual "point" document.Shapes.Head.Name "a shape keeps its constructor name"
         assertEqual [ "x"; "y" ] document.Shapes.Head.Fields "a shape keeps its ordered fields"
     | Error error -> assertEqual "ok" (ProseParser.describeError error) "a book parses a shape declaration")

    (match ProseParser.parseBook bookVocabulary "shape none.\nlogic main = 1." with
     | Ok document -> assertEqual 0 document.Shapes.Head.Fields.Length "a shape may declare no fields"
     | Error error -> assertEqual "ok" (ProseParser.describeError error) "a shape may declare no fields")

    (match ProseParser.parseBook bookVocabulary "shape point with x y.\nlogic main = point(1 2)." with
     | Ok document ->
         let expected =
             ExpressionLogic.Message(
                 "point",
                 [
                     ExpressionLogic.Literal(ExpressionLogic.NumberLiteral 1.0)
                     ExpressionLogic.Literal(ExpressionLogic.NumberLiteral 2.0)
                 ]
             )

         assertEqual expected document.Definitions.Head.Body "a declared shape constructs a message value"
     | Error error -> assertEqual "ok" (ProseParser.describeError error) "a declared shape constructs a message value")

    (match ProseParser.parseBook bookVocabulary "shape point with x y.\nlogic call point = point(1 2)." with
     | Ok document ->
         assertEqual
             (ExpressionLogic.Call(
                 ExpressionLogic.Word "point",
                 [
                     ExpressionLogic.Literal(ExpressionLogic.NumberLiteral 1.0)
                     ExpressionLogic.Literal(ExpressionLogic.NumberLiteral 2.0)
                 ]
             ))
             document.Definitions.Head.Body
             "a parameter that shadows a shape stays a call"
     | Error error -> assertEqual "ok" (ProseParser.describeError error) "a parameter that shadows a shape stays a call")

    (match ProseParser.parseProgram bookVocabulary "shape point with x y." with
     | Error(ProseParser.ShapeOutsideBook _) -> assertEqual true true "a shape in prose is refused"
     | _ -> assertEqual true false "a shape in prose is refused")

    (match ProseParser.parseBook bookVocabulary "shape point with x.\nshape point with y.\nlogic main = 1." with
     | Error(ProseParser.DuplicateShape _) -> assertEqual true true "a duplicate shape is refused"
     | _ -> assertEqual true false "a duplicate shape is refused")

    (match ProseParser.parseBook bookVocabulary "shape point with x.\nlogic point = 1." with
     | Error(ProseParser.ShapeNameConflict _) -> assertEqual true true "a shape and a definition cannot share a name"
     | _ -> assertEqual true false "a shape and a definition cannot share a name")

    (match ProseParser.parseBook bookVocabulary "shape point with x y.\nlogic main = point(1)." with
     | Error(ProseParser.ShapeArityMismatch _) -> assertEqual true true "a construction checks the field count"
     | _ -> assertEqual true false "a construction checks the field count")

    (match ProseParser.parseBook bookVocabulary "shape .\nlogic main = 1." with
     | Error(ProseParser.ExpectedShapeName _) -> assertEqual true true "a shape needs a constructor name"
     | _ -> assertEqual true false "a shape needs a constructor name")

    (match ProseParser.parseBook bookVocabulary "shape point with .\nlogic main = 1." with
     | Error(ProseParser.ExpectedShapeFields _) -> assertEqual true true "a shape needs a field after with"
     | _ -> assertEqual true false "a shape needs a field after with")

    let constructorPath =
        markerPath
            "shape point with x y.\nlogic first p = match p, when point(a b) then a, otherwise 0 close.\nlogic main = first(point(7 9)).\n"

    (match BookRunner.cast shellState0 constructorPath (Some "main") [] with
     | Ok final ->
         match Stack.popResolved final.Store final.Stack with
         | Some(tensor, _) -> assertEqual 7.0 (Tensor.item tensor 0) "a constructed shape destructures through match"
         | None -> assertEqual true false "a constructed shape destructures through match"
     | Error reason -> assertEqual "ok" reason "a constructed shape destructures through match")

    System.IO.File.Delete constructorPath

    let zeroFieldPath =
        markerPath "shape none.\nlogic main = match none(), when none() then 1, otherwise 0 close.\n"

    (match BookRunner.cast shellState0 zeroFieldPath (Some "main") [] with
     | Ok final ->
         match Stack.popResolved final.Store final.Stack with
         | Some(tensor, _) -> assertEqual 1.0 (Tensor.item tensor 0) "a zero-field shape is an atom"
         | None -> assertEqual true false "a zero-field shape is an atom"
     | Error reason -> assertEqual "ok" reason "a zero-field shape is an atom")

    System.IO.File.Delete zeroFieldPath

    printfn "Real numbers:"

    (match ProseParser.parseBook bookVocabulary "logic main = 3.5." with
     | Ok document ->
         assertEqual
             (ExpressionLogic.Literal(ExpressionLogic.NumberLiteral 3.5))
             document.Definitions.Head.Body
             "a fractional literal parses"
     | Error error -> assertEqual "ok" (ProseParser.describeError error) "a fractional literal parses")

    (match ProseParser.parseBook bookVocabulary "logic main = -0.25." with
     | Ok document ->
         assertEqual
             (ExpressionLogic.Literal(ExpressionLogic.NumberLiteral -0.25))
             document.Definitions.Head.Body
             "a negative fractional literal parses"
     | Error error -> assertEqual "ok" (ProseParser.describeError error) "a negative fractional literal parses")

    (match ProseParser.parseBook bookVocabulary "logic main = 1." with
     | Ok document ->
         assertEqual
             (ExpressionLogic.Literal(ExpressionLogic.NumberLiteral 1.0))
             document.Definitions.Head.Body
             "an integer keeps its sentence period"
     | Error error -> assertEqual "ok" (ProseParser.describeError error) "an integer keeps its sentence period")

    (match ProseParser.parseBook bookVocabulary "logic main = .5." with
     | Error(ProseParser.ExpectedExpression _) -> assertEqual true true "a leading-dot number is refused"
     | _ -> assertEqual true false "a leading-dot number is refused")

    let realArithmeticPath = markerPath "logic main = add(1.5 2.5).\n"

    (match BookRunner.cast shellState0 realArithmeticPath (Some "main") [] with
     | Ok final ->
         match Stack.popResolved final.Store final.Stack with
         | Some(tensor, _) -> assertEqual 4.0 (Tensor.item tensor 0) "real arithmetic uses the existing words"
         | None -> assertEqual true false "real arithmetic uses the existing words"
     | Error reason -> assertEqual "ok" reason "real arithmetic uses the existing words")

    System.IO.File.Delete realArithmeticPath

    let realPatternPath =
        markerPath "logic main = match 1.5, when 1.5 then 1, otherwise 0 close.\n"

    (match BookRunner.cast shellState0 realPatternPath (Some "main") [] with
     | Ok final ->
         match Stack.popResolved final.Store final.Stack with
         | Some(tensor, _) -> assertEqual 1.0 (Tensor.item tensor 0) "a real pattern matches its value"
         | None -> assertEqual true false "a real pattern matches its value"
     | Error reason -> assertEqual "ok" reason "a real pattern matches its value")

    System.IO.File.Delete realPatternPath

    printfn "Local binding:"

    (match ProseParser.parseBook bookVocabulary "logic main = let y = 1 in y." with
     | Ok document ->
         assertEqual
             (ExpressionLogic.Let(
                 "y",
                 ExpressionLogic.Literal(ExpressionLogic.NumberLiteral 1.0),
                 ExpressionLogic.Word "y"
             ))
             document.Definitions.Head.Body
             "a local binding parses its name, value, and body"
     | Error error ->
         assertEqual "ok" (ProseParser.describeError error) "a local binding parses its name, value, and body")

    let localValuePath = markerPath "logic main = let y = add(1 2) in multiply(y y).\n"

    (match BookRunner.cast shellState0 localValuePath (Some "main") [] with
     | Ok final ->
         match Stack.popResolved final.Store final.Stack with
         | Some(tensor, _) -> assertEqual 9.0 (Tensor.item tensor 0) "a local value is bound before the body"
         | None -> assertEqual true false "a local value is bound before the body"
     | Error reason -> assertEqual "ok" reason "a local value is bound before the body")

    System.IO.File.Delete localValuePath

    let nestedLocalPath =
        markerPath "logic main = let a = 1 in let b = 2 in add(a b).\n"

    (match BookRunner.cast shellState0 nestedLocalPath (Some "main") [] with
     | Ok final ->
         match Stack.popResolved final.Store final.Stack with
         | Some(tensor, _) -> assertEqual 3.0 (Tensor.item tensor 0) "local bindings nest"
         | None -> assertEqual true false "local bindings nest"
     | Error reason -> assertEqual "ok" reason "local bindings nest")

    System.IO.File.Delete nestedLocalPath

    let shadowParameterPath =
        markerPath "logic f x = let x = 2 in x.\nlogic main = f(9).\n"

    (match BookRunner.cast shellState0 shadowParameterPath (Some "main") [] with
     | Ok final ->
         match Stack.popResolved final.Store final.Stack with
         | Some(tensor, _) -> assertEqual 2.0 (Tensor.item tensor 0) "a local binding shadows a parameter"
         | None -> assertEqual true false "a local binding shadows a parameter"
     | Error reason -> assertEqual "ok" reason "a local binding shadows a parameter")

    System.IO.File.Delete shadowParameterPath

    let shadowShapePath =
        markerPath "shape point with x y.\nlogic main = let point = 7 in point.\n"

    (match BookRunner.cast shellState0 shadowShapePath (Some "main") [] with
     | Ok final ->
         match Stack.popResolved final.Store final.Stack with
         | Some(tensor, _) -> assertEqual 7.0 (Tensor.item tensor 0) "a local binding shadows a shape name"
         | None -> assertEqual true false "a local binding shadows a shape name"
     | Error reason -> assertEqual "ok" reason "a local binding shadows a shape name")

    System.IO.File.Delete shadowShapePath

    (match ProseShell.runTextWith [] None "let y = 2 in add(y y)." with
     | ProseShell.ProseCompleted(ProseShell.ProseNumber number, status) ->
         assertEqual (4.0, 0) (number, status) "a prose sentence binds a local"
     | outcome -> assertEqual "completed number" (showValue (box outcome)) "a prose sentence binds a local")

    (match ProseParser.parseBook bookVocabulary "logic main = let = 1 in 2." with
     | Error(ProseParser.ExpectedBindingName _) -> assertEqual true true "a local binding needs a name"
     | _ -> assertEqual true false "a local binding needs a name")

    (match ProseParser.parseBook bookVocabulary "logic main = let y 1 in y." with
     | Error(ProseParser.ExpectedEquals _) -> assertEqual true true "a local binding needs ="
     | _ -> assertEqual true false "a local binding needs =")

    (match ProseParser.parseBook bookVocabulary "logic main = let y = 1 y." with
     | Error(ProseParser.ExpectedIn _) -> assertEqual true true "a local binding needs in"
     | _ -> assertEqual true false "a local binding needs in")

    printfn "Multiple dispatch:"

    (match
        ProseParser.parseBook
            bookVocabulary
            "generic area with 1.\nshape point with x y.\nmethod area(p : point) = 1.\nlogic main = area(point(1 2)).\n"
     with
     | Ok document ->
         assertEqual
             [ ("area", 1) ]
             (document.Generics |> List.map (fun generic -> generic.Name, generic.Arity))
             "a book parses a generic declaration"

         assertEqual 1 document.Methods.Length "a book parses a method declaration"

         assertEqual
             true
             (document.Definitions
              |> List.exists (fun definition -> definition.Synthetic && definition.Name = "$dispatch:area"))
             "a generic synthesizes a dispatcher definition"
     | Error error -> assertEqual "ok" (ProseParser.describeError error) "a book parses a generic declaration")

    let dispatchBookPath =
        markerPath
            "generic area with 1.\nshape point with x y.\nshape circle with r.\nmethod area(p : point) = 1.\nmethod area(p : circle) = 2.\nlogic first = area(point(2 3)).\nlogic second = area(circle(5)).\n"

    (match BookRunner.cast shellState0 dispatchBookPath (Some "first") [] with
     | Ok final ->
         match Stack.popResolved final.Store final.Stack with
         | Some(tensor, _) ->
             assertEqual 1.0 (Tensor.item tensor 0) "a generic selects the method for the argument shape"
         | None -> assertEqual true false "a generic selects the method for the argument shape"
     | Error reason -> assertEqual "ok" reason "a generic selects the method for the argument shape")

    (match BookRunner.cast shellState0 dispatchBookPath (Some "second") [] with
     | Ok final ->
         match Stack.popResolved final.Store final.Stack with
         | Some(tensor, _) -> assertEqual 2.0 (Tensor.item tensor 0) "each shape selects its own method"
         | None -> assertEqual true false "each shape selects its own method"
     | Error reason -> assertEqual "ok" reason "each shape selects its own method")

    System.IO.File.Delete dispatchBookPath

    let dispatchExtensionPath =
        markerPath
            "generic area with 1.\nshape square with s.\nlogic main = area(square(2)).\nmethod area(p : square) = 3.\n"

    (match BookRunner.cast shellState0 dispatchExtensionPath (Some "main") [] with
     | Ok final ->
         match Stack.popResolved final.Store final.Stack with
         | Some(tensor, _) -> assertEqual 3.0 (Tensor.item tensor 0) "a later method extends the generic"
         | None -> assertEqual true false "a later method extends the generic"
     | Error reason -> assertEqual "ok" reason "a later method extends the generic")

    System.IO.File.Delete dispatchExtensionPath

    let dispatchTwoArgumentPath =
        markerPath
            "generic combine with 2.\nshape point with x y.\nshape circle with r.\nmethod combine(a : point b : point) = 6.\nmethod combine(a : point b : circle) = 5.\nlogic main = combine(point(1 2) circle(3)).\n"

    (match BookRunner.cast shellState0 dispatchTwoArgumentPath (Some "main") [] with
     | Ok final ->
         match Stack.popResolved final.Store final.Stack with
         | Some(tensor, _) -> assertEqual 5.0 (Tensor.item tensor 0) "dispatch matches every argument shape"
         | None -> assertEqual true false "dispatch matches every argument shape"
     | Error reason -> assertEqual "ok" reason "dispatch matches every argument shape")

    System.IO.File.Delete dispatchTwoArgumentPath

    let multiParameterPath =
        markerPath
            "logic sub a b = subtract(a b).\nlogic pick a b c = add(a multiply(b c)).\nlogic first = sub(9 4).\nlogic second = pick(1 2 3).\n"

    (match BookRunner.cast shellState0 multiParameterPath (Some "first") [] with
     | Ok final ->
         match Stack.popResolved final.Store final.Stack with
         | Some(tensor, _) -> assertEqual 5.0 (Tensor.item tensor 0) "a two-parameter call binds its arguments in order"
         | None -> assertEqual true false "a two-parameter call binds its arguments in order"
     | Error reason -> assertEqual "ok" reason "a two-parameter call binds its arguments in order")

    (match BookRunner.cast shellState0 multiParameterPath (Some "second") [] with
     | Ok final ->
         match Stack.popResolved final.Store final.Stack with
         | Some(tensor, _) ->
             assertEqual 7.0 (Tensor.item tensor 0) "a three-parameter call binds its arguments in order"
         | None -> assertEqual true false "a three-parameter call binds its arguments in order"
     | Error reason -> assertEqual "ok" reason "a three-parameter call binds its arguments in order")

    System.IO.File.Delete multiParameterPath

    let portProofPath =
        markerPath
            "shape point with x y.\ngeneric area with 1.\nmethod area(p : point) = match p, when point(a b) then multiply(a b), otherwise 0 close.\ncycle countdown n = match n, when 0 then 1, otherwise multiply(n countdown(subtract(n 1))) close.\nlogic applytwice f x = f(f(x)).\nlogic main = add(area(point(3 4)) countdown(4)).\nlogic higher = applytwice(logic (x) = add(x 1) close 3).\n"

    (match BookRunner.cast shellState0 portProofPath (Some "main") [] with
     | Ok final ->
         match Stack.popResolved final.Store final.Stack with
         | Some(tensor, _) ->
             assertEqual 36.0 (Tensor.item tensor 0) "a record, dispatch, and recursion run through one book"
         | None -> assertEqual true false "a record, dispatch, and recursion run through one book"
     | Error reason -> assertEqual "ok" reason "a record, dispatch, and recursion run through one book")

    (match BookRunner.cast shellState0 portProofPath (Some "higher") [] with
     | Ok final ->
         match Stack.popResolved final.Store final.Stack with
         | Some(tensor, _) -> assertEqual 5.0 (Tensor.item tensor 0) "a higher-order call runs through the same book"
         | None -> assertEqual true false "a higher-order call runs through the same book"
     | Error reason -> assertEqual "ok" reason "a higher-order call runs through the same book")

    System.IO.File.Delete portProofPath

    let decisionTablePath =
        markerPath
            """shape nil.
shape cons with head tail.
shape guard with field comparison threshold.
shape row with guards outcome.
shape table with policy rows.
shape subject with health score.
shape selected with index outcome.
shape nomatch.
shape ambiguous with indices.
shape unique.
shape firstwins.
shape mostguards.
logic healthof s = match s, when subject(h sc) then h, otherwise 0 close.
logic scoreof s = match s, when subject(h sc) then sc, otherwise 0 close.
logic fieldof s f = match f, when "health" then healthof(s), when "score" then scoreof(s), otherwise 0 close.
logic atleast v t = match less than(v t), when 0 then 1, otherwise 0 close.
logic atmost v t = match greater than(v t), when 0 then 1, otherwise 0 close.
logic compare v c t = match c, when "greater than" then greater than(v t), when "at least" then atleast(v t), when "less than" then less than(v t), when "at most" then atmost(v t), when "equal to" then equal to(v t), otherwise 0 close.
logic guardholds g s = match g, when guard(f c t) then compare(fieldof(s f) c t), otherwise 0 close.
cycle allguards gs s = match gs, when nil() then 1, when cons(g rest) then multiply(guardholds(g s) allguards(rest s)), otherwise 0 close.
logic rowholds r s = match r, when row(gs o) then allguards(gs s), otherwise 0 close.
logic rowoutcome r = match r, when row(gs o) then o, otherwise 0 close.
cycle length xs = match xs, when nil() then 0, when cons(h t) then add(1 length(t)), otherwise 0 close.
logic guardcount r = match r, when row(gs o) then length(gs), otherwise 0 close.
cycle countmatches rows s = match rows, when nil() then 0, when cons(r rest) then add(rowholds(r s) countmatches(rest s)), otherwise 0 close.
cycle firstmatch rows s i = match rows, when nil() then nomatch(), when cons(r rest) then match rowholds(r s), when 1 then selected(i rowoutcome(r)), otherwise firstmatch(rest s add(i 1)) close, otherwise nomatch() close.
cycle collectindices rows s i = match rows, when nil() then nil(), when cons(r rest) then match rowholds(r s), when 1 then cons(i collectindices(rest s add(i 1))), otherwise collectindices(rest s add(i 1)) close, otherwise nil() close.
cycle bestmatch rows s i bestindex bestoutcome found bestcount = match rows, when nil() then match found, when 1 then selected(bestindex bestoutcome), otherwise nomatch() close, when cons(r rest) then match rowholds(r s), when 1 then match greater than(guardcount(r) bestcount), when 1 then bestmatch(rest s add(i 1) i rowoutcome(r) 1 guardcount(r)), otherwise bestmatch(rest s add(i 1) bestindex bestoutcome 1 bestcount) close, otherwise bestmatch(rest s add(i 1) bestindex bestoutcome found bestcount) close, otherwise nomatch() close.
logic choosepolicy policy rows s = match countmatches(rows s), when 0 then nomatch(), when 1 then firstmatch(rows s 0), otherwise match policy, when unique() then ambiguous(collectindices(rows s 0)), when firstwins() then firstmatch(rows s 0), when mostguards() then bestmatch(rows s 0 -1 0 0 0), otherwise nomatch() close close.
logic select t s = match t, when table(p rows) then choosepolicy(p rows s), otherwise nomatch() close.
logic resultcode r = match r, when selected(i o) then add(multiply(i 100) o), when nomatch() then -1, when ambiguous(xs) then -2, otherwise -3 close.
logic ambiguities r = match r, when ambiguous(xs) then xs, otherwise nil() close.
logic rowsfirst = cons(row(cons(guard("health" "greater than" 10) nil()) 1) cons(row(cons(guard("health" "greater than" 20) nil()) 2) nil())).
logic rowsunique = cons(row(cons(guard("health" "greater than" 10) nil()) 1) cons(row(cons(guard("health" "less than" 10) nil()) 2) nil())).
logic rowsoverlap = cons(row(cons(guard("health" "greater than" 10) nil()) 1) cons(row(cons(guard("health" "greater than" 20) nil()) 2) nil())).
logic rowspriority = cons(row(cons(guard("health" "greater than" 10) nil()) 1) cons(row(cons(guard("health" "greater than" 10) cons(guard("score" "greater than" 0) nil())) 2) nil())).
logic firstboth = resultcode(select(table(firstwins() rowsfirst) subject(25 5))).
logic firstnone = resultcode(select(table(firstwins() rowsfirst) subject(5 5))).
logic uniquefirst = resultcode(select(table(unique() rowsunique) subject(25 5))).
logic uniquesecond = resultcode(select(table(unique() rowsunique) subject(5 5))).
logic uniquenone = resultcode(select(table(unique() rowsunique) subject(10 5))).
logic uniqueoverlap = resultcode(select(table(unique() rowsoverlap) subject(25 5))).
logic prioritymost = resultcode(select(table(mostguards() rowspriority) subject(25 5))).
logic priorityone = resultcode(select(table(mostguards() rowspriority) subject(25 0))).
logic overlaphead = match ambiguities(select(table(unique() rowsoverlap) subject(25 5))), when cons(h t) then h, otherwise -1 close.
"""

    let checkPort (word: string) (expected: float) =
        match BookRunner.cast shellState0 decisionTablePath (Some word) [] with
        | Ok final ->
            match Stack.popResolved final.Store final.Stack with
            | Some(tensor, _) -> assertEqual expected (Tensor.item tensor 0) ("the decision-table port returns " + word)
            | None -> assertEqual true false ("the decision-table port returns " + word)
        | Error reason -> assertEqual "ok" reason ("the decision-table port returns " + word)

    [
        ("firstboth", 1.0)
        ("firstnone", -1.0)
        ("uniquefirst", 1.0)
        ("uniquesecond", 102.0)
        ("uniquenone", -1.0)
        ("uniqueoverlap", -2.0)
        ("prioritymost", 102.0)
        ("priorityone", 1.0)
        ("overlaphead", 0.0)
    ]
    |> List.iter (fun (word, expected) -> checkPort word expected)

    System.IO.File.Delete decisionTablePath

    let listModulePath =
        markerPath
            """shape nil.
shape cons with head tail.
logic head xs = match xs, when cons(h t) then h, otherwise 0 close.
logic second xs = match xs, when cons(h t) then head(t), otherwise 0 close.
logic third xs = match xs, when cons(h t) then second(t), otherwise 0 close.
cycle length xs = match xs, when nil() then 0, when cons(h t) then add(1 length(t)), otherwise 0 close.
cycle map f xs = match xs, when nil() then nil(), when cons(h t) then cons(f(h) map(f t)), otherwise nil() close.
cycle filter p xs = match xs, when nil() then nil(), when cons(h t) then match p(h), when 1 then cons(h filter(p t)), otherwise filter(p t) close, otherwise nil() close.
cycle fold f acc xs = match xs, when nil() then acc, when cons(h t) then fold(f f(acc h) t), otherwise acc close.
cycle append xs ys = match xs, when nil() then ys, when cons(h t) then cons(h append(t ys)), otherwise ys close.
cycle reverseacc xs acc = match xs, when nil() then acc, when cons(h t) then reverseacc(t cons(h acc)), otherwise acc close.
logic reverse xs = reverseacc(xs nil()).
cycle contains x xs = match xs, when nil() then 0, when cons(h t) then match equals(h x), when 1 then 1, otherwise contains(x t) close, otherwise 0 close.
cycle insert x xs = match xs, when nil() then cons(x nil()), when cons(h t) then match greater than(h x), when 1 then cons(x xs), otherwise cons(h insert(x t)) close, otherwise cons(x nil()) close.
cycle sort xs = match xs, when nil() then nil(), when cons(h t) then insert(h sort(t)), otherwise nil() close.
logic nums = cons(3 cons(1 cons(2 nil()))).
logic lengths = length(nums).
logic doubledsum = fold(logic (a b) = add(a b) close 0 map(logic (x) = multiply(x 2) close nums)).
logic filteredlength = length(filter(logic (x) = greater than(x 1) close nums)).
logic filteredhead = head(filter(logic (x) = greater than(x 1) close nums)).
logic total = fold(logic (a b) = add(a b) close 0 nums).
logic appendedlength = length(append(nums cons(4 nil()))).
logic appendedlast = head(reverse(append(nums cons(4 nil())))).
logic reversedhead = head(reverse(nums)).
logic reversedlength = length(reverse(nums)).
logic hastwo = contains(2 nums).
logic hasnine = contains(9 nums).
logic sortedhead = head(sort(nums)).
logic sortedsecond = second(sort(nums)).
logic sortedthird = third(sort(nums)).
logic sortedsum = fold(logic (a b) = add(a b) close 0 sort(nums)).
"""

    let checkList (word: string) (expected: float) =
        match BookRunner.cast shellState0 listModulePath (Some word) [] with
        | Ok final ->
            match Stack.popResolved final.Store final.Stack with
            | Some(tensor, _) -> assertEqual expected (Tensor.item tensor 0) ("the list module port returns " + word)
            | None -> assertEqual true false ("the list module port returns " + word)
        | Error reason -> assertEqual "ok" reason ("the list module port returns " + word)

    [
        ("lengths", 3.0)
        ("doubledsum", 12.0)
        ("filteredlength", 2.0)
        ("filteredhead", 3.0)
        ("total", 6.0)
        ("appendedlength", 4.0)
        ("appendedlast", 4.0)
        ("reversedhead", 2.0)
        ("reversedlength", 3.0)
        ("hastwo", 1.0)
        ("hasnine", 0.0)
        ("sortedhead", 1.0)
        ("sortedsecond", 2.0)
        ("sortedthird", 3.0)
        ("sortedsum", 6.0)
    ]
    |> List.iter (fun (word, expected) -> checkList word expected)

    System.IO.File.Delete listModulePath

    let patternAnalysisPath =
        markerPath
            """shape nil.
shape cons with head tail.
shape wildcard.
shape var with name role.
shape numberpattern with value.
shape textpattern with value.
shape atompattern with value.
shape typedpattern with sort child.
shape constructorpattern with name children.
shape clause with pattern guarded.
shape kind with name arity closed constructors.
shape nokind.
shape exhaustive.
shape notexhaustive.
shape undecided with reason.
shape analysis with unreachable exhaustiveness.
cycle length xs = match xs, when nil() then 0, when cons(h t) then add(1 length(t)), otherwise 0 close.
cycle append xs ys = match xs, when nil() then ys, when cons(h t) then cons(h append(t ys)), otherwise ys close.
cycle reverseacc xs acc = match xs, when nil() then acc, when cons(h t) then reverseacc(t cons(h acc)), otherwise acc close.
logic reverse xs = reverseacc(xs nil()).
cycle member x xs = match xs, when nil() then 0, when cons(h t) then match equals(h x), when 1 then 1, otherwise member(x t) close, otherwise 0 close.
cycle catchall p = match p, when wildcard() then 1, when var(n r) then match less than(r 2), when 1 then 1, otherwise 0 close, when typedpattern(s c) then catchall(c), otherwise 0 close.
logic samelength a b = equals(length(a) length(b)).
cycle subsumes earlier later = match catchall(earlier), when 1 then 1, otherwise match earlier, when wildcard() then 1, when var(n1 r1) then match later, when var(n2 r2) then equals(n1 n2), otherwise 0 close, when numberpattern(v1) then match later, when numberpattern(v2) then equals(v1 v2), otherwise 0 close, when textpattern(v1) then match later, when textpattern(v2) then equals(v1 v2), otherwise 0 close, when atompattern(v1) then match later, when atompattern(v2) then equals(v1 v2), otherwise 0 close, when typedpattern(s1 c1) then match later, when typedpattern(s2 c2) then multiply(equals(s1 s2) subsumes(c1 c2)), otherwise 0 close, when constructorpattern(n1 cs1) then match later, when constructorpattern(n2 cs2) then multiply(equals(n1 n2) multiply(samelength(cs1 cs2) allsubsume(cs1 cs2))), otherwise 0 close, otherwise 0 close close.
and allsubsume cs1 cs2 = match cs1, when nil() then match cs2, when nil() then 1, otherwise 0 close, when cons(h t) then match cs2, when cons(h2 t2) then multiply(subsumes(h h2) allsubsume(t t2)), otherwise 0 close, otherwise 0 close.
cycle coveredby earlier p = match earlier, when nil() then 0, when cons(h t) then match subsumes(h p), when 1 then 1, otherwise coveredby(t p) close, otherwise 0 close.
cycle unreachableacc index covering unreachable clauses = match clauses, when nil() then reverse(unreachable), when cons(c rest) then match c, when clause(p g) then match coveredby(covering p), when 1 then unreachableacc(add(index 1) covering cons(index unreachable) rest), otherwise match g, when 1 then unreachableacc(add(index 1) covering unreachable rest), otherwise unreachableacc(add(index 1) append(covering cons(p nil())) unreachable rest) close close, otherwise reverse(unreachable) close, otherwise reverse(unreachable) close.
logic unreachable clauses = unreachableacc(0 nil() nil() clauses).
cycle hasunguardedcatchall clauses = match clauses, when nil() then 0, when cons(c rest) then match c, when clause(p g) then match g, when 0 then match catchall(p), when 1 then 1, otherwise hasunguardedcatchall(rest) close, otherwise hasunguardedcatchall(rest) close, otherwise 0 close, otherwise 0 close.
cycle allcatchall cs = match cs, when nil() then 1, when cons(h t) then multiply(catchall(h) allcatchall(t)), otherwise 0 close.
cycle coverednames clauses acc = match clauses, when nil() then acc, when cons(c rest) then match c, when clause(p g) then match g, when 0 then match p, when constructorpattern(n cs) then match allcatchall(cs), when 1 then coverednames(rest cons(n acc)), otherwise coverednames(rest acc) close, otherwise coverednames(rest acc) close, otherwise coverednames(rest acc) close, otherwise acc close, otherwise acc close.
cycle missingany constructors covered = match constructors, when nil() then 0, when cons(h t) then match member(h covered), when 1 then missingany(t covered), otherwise 1 close, otherwise 0 close.
logic exhaustiveness k clauses = match hasunguardedcatchall(clauses), when 1 then exhaustive(), otherwise match k, when nokind() then undecided(0), when kind(n a closed constructors) then match closed, when 0 then undecided(1), otherwise match missingany(constructors coverednames(clauses nil())), when 1 then notexhaustive(), otherwise exhaustive() close close, otherwise undecided(2) close close.
logic analyze k clauses = analysis(unreachable(clauses) exhaustiveness(k clauses)).
logic unreachablecount a = match a, when analysis(us e) then length(us), otherwise -1 close.
logic firstunreachable a = match a, when analysis(us e) then match us, when cons(h t) then h, otherwise -1 close, otherwise -1 close.
logic exhaustivenesscode a = match a, when analysis(us e) then match e, when exhaustive() then 0, when notexhaustive() then 1, when undecided(r) then 2, otherwise -1 close, otherwise -1 close.
logic kind2 = kind(1 2 1 cons(10 cons(11 nil()))).
logic kindopen = kind(1 2 0 cons(10 cons(11 nil()))).
logic clauseswild = cons(clause(wildcard() 0) cons(clause(numberpattern(1) 0) nil())).
logic clausesdup = cons(clause(numberpattern(1) 0) cons(clause(numberpattern(1) 0) nil())).
logic clausesdiff = cons(clause(numberpattern(1) 0) cons(clause(numberpattern(2) 0) nil())).
logic clausesguard = cons(clause(numberpattern(1) 1) cons(clause(numberpattern(1) 0) nil())).
logic clausesclosed = cons(clause(constructorpattern(10 cons(wildcard() nil())) 0) cons(clause(constructorpattern(11 cons(wildcard() nil())) 0) nil())).
logic clausesmissing = cons(clause(constructorpattern(10 cons(wildcard() nil())) 0) nil()).
logic clausestyped = cons(clause(typedpattern(99 wildcard()) 0) cons(clause(numberpattern(1) 0) nil())).
logic clausesctorchild = cons(clause(constructorpattern(10 cons(wildcard() nil())) 0) cons(clause(constructorpattern(10 cons(numberpattern(1) nil())) 0) nil())).
logic clausesvar = cons(clause(var(5 0) 0) cons(clause(var(5 1) 0) nil())).
logic wildcount = unreachablecount(analyze(nokind() clauseswild)).
logic wildfirst = firstunreachable(analyze(nokind() clauseswild)).
logic wildcode = exhaustivenesscode(analyze(nokind() clauseswild)).
logic dupcount = unreachablecount(analyze(nokind() clausesdup)).
logic diffcount = unreachablecount(analyze(nokind() clausesdiff)).
logic guardcount = unreachablecount(analyze(nokind() clausesguard)).
logic guardcode = exhaustivenesscode(analyze(nokind() clausesguard)).
logic closedcode = exhaustivenesscode(analyze(kind2 clausesclosed)).
logic missingcode = exhaustivenesscode(analyze(kind2 clausesmissing)).
logic opencode = exhaustivenesscode(analyze(kindopen clausesclosed)).
logic typedcount = unreachablecount(analyze(nokind() clausestyped)).
logic ctorcount = unreachablecount(analyze(nokind() clausesctorchild)).
logic varcount = unreachablecount(analyze(nokind() clausesvar)).
logic nokindcode = exhaustivenesscode(analyze(nokind() clausesdiff)).
"""

    let checkAnalysis (word: string) (expected: float) =
        match BookRunner.cast shellState0 patternAnalysisPath (Some word) [] with
        | Ok final ->
            match Stack.popResolved final.Store final.Stack with
            | Some(tensor, _) ->
                assertEqual expected (Tensor.item tensor 0) ("the pattern-analysis port returns " + word)
            | None -> assertEqual true false ("the pattern-analysis port returns " + word)
        | Error reason -> assertEqual "ok" reason ("the pattern-analysis port returns " + word)

    [
        ("wildcount", 1.0)
        ("wildfirst", 1.0)
        ("wildcode", 0.0)
        ("dupcount", 1.0)
        ("diffcount", 0.0)
        ("guardcount", 0.0)
        ("guardcode", 2.0)
        ("closedcode", 0.0)
        ("missingcode", 1.0)
        ("opencode", 2.0)
        ("typedcount", 1.0)
        ("ctorcount", 1.0)
        ("varcount", 1.0)
        ("nokindcode", 2.0)
    ]
    |> List.iter (fun (word, expected) -> checkAnalysis word expected)

    System.IO.File.Delete patternAnalysisPath

    let dispatchCheckPath =
        markerPath
            "generic area with 1.\nshape point with x y.\nmethod area(p : point) = 1.\nlogic main = area(point(1 2)).\n"

    (match BookRunner.check shellState0 dispatchCheckPath with
     | Ok() -> assertEqual true true "a generic book passes the check gate"
     | Error reason -> assertEqual "ok" reason "a generic book passes the check gate")

    System.IO.File.Delete dispatchCheckPath

    let dispatchZeroArgumentPath =
        markerPath "generic answer with 0.\nmethod answer() = 42.\nlogic main = answer.\n"

    (match BookRunner.cast shellState0 dispatchZeroArgumentPath (Some "main") [] with
     | Ok final ->
         match Stack.popResolved final.Store final.Stack with
         | Some(tensor, _) -> assertEqual 42.0 (Tensor.item tensor 0) "a zero-arity generic dispatches"
         | None -> assertEqual true false "a zero-arity generic dispatches"
     | Error reason -> assertEqual "ok" reason "a zero-arity generic dispatches")

    System.IO.File.Delete dispatchZeroArgumentPath

    let dispatchNoMethodPath =
        markerPath
            "generic area with 1.\nshape point with x y.\nshape square with s.\nmethod area(p : point) = 1.\nlogic main = area(square(2)).\n"

    (match BookRunner.cast shellState0 dispatchNoMethodPath (Some "main") [] with
     | Error reason -> assertEqual true (reason.Contains "NoApplicableMethod: area") "a missing method refuses by name"
     | Ok _ -> assertEqual true false "a missing method refuses by name")

    System.IO.File.Delete dispatchNoMethodPath

    (match ProseParser.parseProgram bookVocabulary "generic area with 1." with
     | Error(ProseParser.GenericOutsideBook _) -> assertEqual true true "a generic in prose is refused"
     | _ -> assertEqual true false "a generic in prose is refused")

    (match ProseParser.parseProgram bookVocabulary "method area(p : point) = 1." with
     | Error(ProseParser.MethodOutsideBook _) -> assertEqual true true "a method in prose is refused"
     | _ -> assertEqual true false "a method in prose is refused")

    (match ProseParser.parseBook bookVocabulary "generic area with 1.\ngeneric area with 1.\nlogic main = 1." with
     | Error(ProseParser.DuplicateGeneric _) -> assertEqual true true "a duplicate generic is refused"
     | _ -> assertEqual true false "a duplicate generic is refused")

    (match ProseParser.parseBook bookVocabulary "generic area with 1.\nlogic area = 1." with
     | Error(ProseParser.GenericNameConflict _) ->
         assertEqual true true "a generic and a definition cannot share a name"
     | _ -> assertEqual true false "a generic and a definition cannot share a name")

    (match
        ProseParser.parseBook bookVocabulary "shape point with x y.\nmethod area(p : point) = 1.\nlogic main = 1."
     with
     | Error(ProseParser.UnknownGeneric _) -> assertEqual true true "a method needs a declared generic"
     | _ -> assertEqual true false "a method needs a declared generic")

    (match
        ProseParser.parseBook
            bookVocabulary
            "generic area with 1.\nshape point with x y.\nmethod area(p : square) = 1.\nlogic main = 1."
     with
     | Error(ProseParser.UnknownShape _) -> assertEqual true true "a method needs a declared shape"
     | _ -> assertEqual true false "a method needs a declared shape")

    (match
        ProseParser.parseBook
            bookVocabulary
            "generic area with 1.\nshape point with x y.\nmethod area(a : point b : point) = 1.\nlogic main = 1."
     with
     | Error(ProseParser.MethodArityMismatch _) -> assertEqual true true "a method matches the generic arity"
     | _ -> assertEqual true false "a method matches the generic arity")

    (match
        ProseParser.parseBook
            bookVocabulary
            "generic area with 1.\nshape point with x y.\nmethod area(p : point) = 1.\nmethod area(p : point) = 2.\nlogic main = 1."
     with
     | Error(ProseParser.DuplicateMethod _) -> assertEqual true true "a repeated method specializer list is refused"
     | _ -> assertEqual true false "a repeated method specializer list is refused")

    (match
        ProseParser.parseBook
            bookVocabulary
            "generic area with 2.\nshape point with x y.\nmethod area(p : point p : point) = 1.\nlogic main = 1."
     with
     | Error(ProseParser.DuplicateParameter _) -> assertEqual true true "a repeated method parameter is refused"
     | _ -> assertEqual true false "a repeated method parameter is refused")

    (match
        ProseParser.parseBook
            bookVocabulary
            "generic area with 1.\nshape point with x y.\nmethod area(p : point) = 1.\nlogic main = area(point(1 2) point(3 4))."
     with
     | Error(ProseParser.GenericCallArityMismatch _) -> assertEqual true true "a generic call matches the generic arity"
     | _ -> assertEqual true false "a generic call matches the generic arity")

    let cachePath = markerPath "logic cached = 1.\n"

    (match BookRunner.load shellState0 cachePath, BookRunner.load shellState0 cachePath with
     | Ok first, Ok second ->
         assertEqual true (obj.ReferenceEquals(first, second)) "an unchanged book is served from the cache"
     | _ -> assertEqual true false "an unchanged book is served from the cache")

    let firstHash =
        match BookRunner.load shellState0 cachePath with
        | Ok first -> Some first.Package.SourceHash
        | Error _ -> None

    System.IO.File.WriteAllText(cachePath, "logic cached = 2.\n")

    (match BookRunner.load shellState0 cachePath with
     | Ok changed ->
         assertEqual false (Some changed.Package.SourceHash = firstHash) "a changed book invalidates the cache key"
     | Error reason -> assertEqual "ok" reason "a changed book invalidates the cache key")

    System.IO.File.Delete cachePath

    (match BookRunner.checkCapabilities [ "shell" ] shellState0 with
     | Error reason -> assertEqual true (reason.Contains "capability shell") "a package capability must be granted"
     | Ok _ -> assertEqual true false "a package capability must be granted")

    (match
        BookRunner.checkCapabilities
            [ "shell" ]
            { shellState0 with
                Capabilities = Set.ofList [ "shell" ]
