     with
     | Ok() -> assertEqual true true "a granted package capability is accepted"
     | Error reason -> assertEqual "ok" reason "a granted package capability is accepted")

    let includeDirectory =
        System.IO.Path.Combine(System.IO.Path.GetTempPath(), "scale-include-" + System.Guid.NewGuid().ToString("N"))

    System.IO.Directory.CreateDirectory includeDirectory |> ignore

    let includedMathPath = System.IO.Path.Combine(includeDirectory, "math.book")
    let includedMainPath = System.IO.Path.Combine(includeDirectory, "main.book")
    let includeCycleAPath = System.IO.Path.Combine(includeDirectory, "cyclea.book")
    let includeCycleBPath = System.IO.Path.Combine(includeDirectory, "cycleb.book")

    System.IO.File.WriteAllText(includedMathPath, "logic double x = multiply(x 2).\n")
    System.IO.File.WriteAllText(includedMainPath, "open math\nlogic main = double(21).\n")
    System.IO.File.WriteAllText(includeCycleAPath, "open cycleb\nlogic a = 1.\n")
    System.IO.File.WriteAllText(includeCycleBPath, "open cyclea\nlogic b = 2.\n")

    (match BookRunner.load shellState0 includedMainPath with
     | Ok book -> assertEqual 1 book.Package.Imports.Length "an include becomes a package import"
     | Error reason -> assertEqual "ok" reason "an include becomes a package import")

    (match BookRunner.cast shellState0 includedMainPath (Some "main") [] with
     | Ok final ->
         match Stack.popResolved final.Store final.Stack with
         | Some(tensor, _) -> assertEqual 42.0 (Tensor.item tensor 0) "an included word is callable"
         | None -> assertEqual true false "an included word is callable"
     | Error reason -> assertEqual "ok" reason "an included word is callable")

    (match BookRunner.load shellState0 includeCycleAPath with
     | Error reason -> assertEqual true (reason.Contains "open cycle") "an open cycle is refused"
     | Ok _ -> assertEqual true false "an open cycle is refused")

    (match BookRunner.load shellState0 includedMainPath with
     | Ok book ->
         match BookRunner.index book with
         | Ok index ->
             assertEqual
                 [ "math"; "main" ]
                 (index.Entries |> List.map (fun entry -> entry.Name))
                 "the index orders included files first"

             assertEqual [ "math" ] index.Entries.[1].Dependencies "the index records include dependencies"
         | Error error -> assertEqual "ok" (BookRunner.describeIndexError error) "the index orders included files first"
     | Error reason -> assertEqual "ok" reason "the index orders included files first")

    (match BookRunner.load shellState0 includedMathPath, BookRunner.load shellState0 includedMainPath with
     | Ok math, Ok main ->
         let mathEntry = ProjectIndex.ofBook math
         assertEqual ProjectIndex.Scroll mathEntry.Kind "a book without an index is a scroll"

         (match ProjectIndex.add mathEntry ProjectIndex.empty with
          | Ok catalog ->
              match ProjectIndex.add (ProjectIndex.ofBook main) catalog with
              | Ok catalog -> assertEqual 2 catalog.Entries.Length "the catalog holds a scroll and a project"
              | Error error ->
                  assertEqual "ok" (ProjectIndex.describeCatalogError error) "the catalog holds a scroll and a project"
          | Error error ->
              assertEqual "ok" (ProjectIndex.describeCatalogError error) "the catalog holds a scroll and a project")

         (match BookRunner.index main with
          | Ok index ->
              match ProjectIndex.directory "mathlib" index.Entries with
              | Ok library -> assertEqual 2 library.Entries.Length "a library index keeps the ordered entries"
              | Error error ->
                  assertEqual "ok" (BookRunner.describeIndexError error) "a library index keeps the ordered entries"
          | Error error ->
              assertEqual "ok" (BookRunner.describeIndexError error) "a library index keeps the ordered entries")
     | _ -> assertEqual true false "a book without an index is a scroll")

    System.IO.Directory.Delete(includeDirectory, true)

    let spellText = "logic main = capture(\"echo\" \"hello\")."

    let shellSpellPath =
        System.IO.Path.Combine(
            System.IO.Path.GetTempPath(),
            "scale-spell-" + System.Guid.NewGuid().ToString("N") + ".book"
        )

    System.IO.File.WriteAllText(shellSpellPath, spellText)

    (match BookRunner.load shellState0 shellSpellPath with
     | Ok book -> assertEqual [ "shell" ] book.Package.Capabilities "a book derives its host-word capabilities"
     | Error reason -> assertEqual "ok" reason "a book derives its host-word capabilities")

    (match
        ProseShell.runTextWith
            [ BookHost.wordAdapter; ShellHost.wordAdapter processShell ]
            (Some(System.IO.Path.GetDirectoryName shellSpellPath))
            ("cast(\"" + shellSpellPath + "\").")
     with
     | ProseShell.ProseCompleted(ProseShell.ProseText text, status) ->
         assertEqual ("hello\n", 0) (text, status) "a prose cast runs a spell's main"
     | outcome -> assertEqual "completed text" (showValue (box outcome)) "a prose cast runs a spell's main")

    (match BookRunner.cast shellState0 mathBookPath (Some "missing") [] with
     | Error reason -> assertEqual true (reason.Contains "missing") "an unknown book word is a named refusal"
     | Ok _ -> assertEqual true false "an unknown book word is a named refusal")

    (match BookRunner.load shellState0 "/definitely/not/a/book.book" with
     | Error _ -> assertEqual true true "a missing book is a refusal"
     | Ok _ -> assertEqual true false "a missing book is a refusal")

    (match BookRunner.runSpell shellState0 spellPath with
     | Ok final ->
         match Stack.popResolved final.Store final.Stack with
         | Some(tensor, _) -> assertEqual 42.0 (Tensor.item tensor 0) "a spell runs its main"
         | None -> assertEqual true false "a spell runs its main"
     | Error reason -> assertEqual "ok" reason "a spell runs its main")

    assertEqual
        (Cli.BookCheck "tool.book")
        (Cli.parseArguments [| "--check"; "tool.book" |])
        "the check flag selects the book check"

    (match BookRunner.check shellState0 mathBookPath with
     | Ok() -> assertEqual true true "a valid book passes the check gate"
     | Error reason -> assertEqual "ok" reason "a valid book passes the check gate")

    assertEqual
        (Cli.BookRun "tool.book")
        (Cli.parseArguments [| "--book"; "tool.book" |])
        "the book flag selects the book runner"

    assertEqual
        (Cli.CastRun("math.book", "double", [ "21" ]))
        (Cli.parseArguments [| "--cast"; "math.book"; "double"; "21" |])
        "the cast flag selects the book cast"

    System.IO.File.Delete mathBookPath
    System.IO.File.Delete spellPath
    System.IO.File.Delete shellSpellPath

    printfn "F# abstraction:"

    let unitExpression = ExpressionLogic.Literal(ExpressionLogic.NumberLiteral 1.0)

    let binding
        (name: string)
        (parameters: string list)
        (kind: FSharpAbstraction.FSharpRecursionKind)
        (calls: string list)
        : FSharpAbstraction.FSharpBinding =
        {
            Name = name
            Parameters = parameters
            Body = unitExpression
            Kind = kind
            Calls = calls
            Range = sourceRange 0 1
        }

    let abstraction: FSharpAbstraction.FSharpAbstraction =
        {
            SchemaVersion = FSharpAbstraction.abstractionSchemaVersion
            Module = "Demo"
            Version = "1"
            SourceHash = "sha256:demo"
            Bindings =
                [
                    binding "f" [ "x" ] FSharpAbstraction.NonRecursive []
                    binding "g" [ "x" ] FSharpAbstraction.Recursive [ "g" ]
                    binding "v" [] (FSharpAbstraction.MutuallyRecursive [ "v" ]) [ "v" ]
                ]
        }

    (match FSharpAbstraction.classify abstraction None with
     | Ok result ->
         assertEqual 3 result.Bindings.Length "the F# abstraction classifies every binding"

         let kindOf name =
             result.Bindings
             |> List.tryFind (fun item -> item.Name = name)
             |> Option.map (fun item -> item.Kind)

         assertEqual (Some PackageLogic.NonRecursiveFunction) (kindOf "f") "an F# let function is non-recursive"
         assertEqual (Some PackageLogic.RecursiveFunction) (kindOf "g") "an F# let rec function is recursive"
         assertEqual (Some(PackageLogic.MutuallyRecursiveFunction [ "v" ])) (kindOf "v") "an F# and group is mutual"
     | Error errors -> assertEqual "ok" (string errors.Length) "the F# abstraction classifies every binding")

    let manifestPackage: FSharpAbstraction.Manifest =
        {
            SchemaVersion = FSharpAbstraction.manifestSchemaVersion
            Package = "Demo"
            Mode = FSharpAbstraction.Mixed
            Bindings =
                [
                    {
                        Name = "f"
                        Kind = FSharpAbstraction.Recursive
                        Reason = None
                    }
                ]
        }

    (match FSharpAbstraction.classify abstraction (Some manifestPackage) with
     | Error errors ->
         assertEqual
             true
             (errors
              |> List.exists (function
                  | FSharpAbstraction.ManifestDisagreement _ -> true
                  | _ -> false))
             "an unexplained manifest disagreement is refused"
     | Ok _ -> assertEqual true false "an unexplained manifest disagreement is refused")

    let explainedManifest =
        { manifestPackage with
            Bindings =
                [
                    {
                        Name = "f"
                        Kind = FSharpAbstraction.Recursive
                        Reason = Some FSharpAbstraction.CrossModule
                    }
                ]
        }

    (match FSharpAbstraction.classify abstraction (Some explainedManifest) with
     | Ok result ->
         assertEqual 1 result.Overrides.Length "an explained manifest override is tracked"

         assertEqual
             (Some PackageLogic.RecursiveFunction)
             (result.Bindings
              |> List.tryFind (fun item -> item.Name = "f")
              |> Option.map (fun item -> item.Kind))
             "an explained manifest override wins"
     | Error _ -> assertEqual true false "an explained manifest override wins")

    let strictManifest =
        { manifestPackage with
            Mode = FSharpAbstraction.Strict
            Bindings = []
        }

    (match FSharpAbstraction.classify abstraction (Some strictManifest) with
     | Error errors ->
         assertEqual
             true
             (errors
              |> List.exists (function
                  | FSharpAbstraction.MissingManifestBinding _ -> true
                  | _ -> false))
             "strict mode requires a manifest entry for every binding"
     | Ok _ -> assertEqual true false "strict mode requires a manifest entry for every binding")

    let manifestJson =
        """{ "schemaVersion": 1, "package": "Demo", "mode": "mixed", "bindings": [ { "name": "f", "kind": "recursive", "reason": "cross-module" } ] }"""

    (match FSharpAbstraction.parseManifest manifestJson with
     | Ok manifest ->
         assertEqual FSharpAbstraction.Mixed manifest.Mode "a manifest parses its mode"
         assertEqual 1 manifest.Bindings.Length "a manifest parses its binding"
     | Error _ -> assertEqual true false "a manifest parses its mode")

    (match FSharpAbstraction.classify abstraction None with
     | Ok result ->
         let metadata = FSharpAbstraction.metadata result.Bindings
         assertEqual "non-recursive-function" (metadata.Head.Kind) "classification metadata carries the kind"
     | Error _ -> assertEqual true false "classification metadata carries the kind")

    let mapped =
        FSharpAbstraction.mapDiagnostic
            {
                FSharpAbstraction.Code = "FS0040"
                Message = "value restriction"
                Range = sourceRange 0 1
            }

    assertEqual FSharpAbstraction.RecursiveValueWithoutInstantiation mapped.Code "FS0040 maps to a Scale diagnostic"

    (match FSharpAbstraction.classify abstraction None with
     | Ok result ->
         match FSharpAbstraction.toPackageDocument abstraction result.Bindings with
         | Ok document ->
             assertEqual 3 document.Units.Length "the F# abstraction lowers to package units"

             assertEqual
                 1
                 (document.Units
                  |> List.find (fun unit -> unit.Name = "f")
                  |> fun unit -> unit.Arity)
                 "a lowered F# function keeps its arity"

             match PackagePortable.ofJson (PackagePortable.toJson document) with
             | Ok parsed ->
                 assertEqual 3 parsed.Units.Length "the lowered F# package round-trips"
                 assertEqual 3 parsed.Groups.Head.Classification.Length "the round-trip keeps classification"
             | Error _ -> assertEqual true false "the lowered F# package round-trips"
         | Error _ -> assertEqual true false "the F# abstraction lowers to package units"
     | Error _ -> assertEqual true false "the F# abstraction lowers to package units")

    let readOffJson =
        """{ "schemaVersion": 1, "module": "Demo", "bindings": [ { "name": "f", "parameters": [ "x" ], "kind": "recursive", "calls": [ "f" ], "startOffset": 0, "endOffset": 10, "body": { "schema": 1, "form": "closed", "kinds": [], "predicates": [], "root": { "tag": "number", "value": 1 } } } ] }"""

    let readOffWithoutBodyJson =
        """{ "schemaVersion": 1, "module": "Demo", "bindings": [ { "name": "f", "parameters": [ "x" ], "kind": "recursive", "calls": [ "f" ], "startOffset": 0, "endOffset": 10 } ] }"""

    (match FSharpAbstraction.parseReadOff readOffJson with
     | Ok readOff ->
         assertEqual 1 readOff.Bindings.Length "the FCS read-off parses its binding"
         assertEqual FSharpAbstraction.Recursive readOff.Bindings.Head.Kind "the FCS read-off keeps the recursion kind"
     | Error _ -> assertEqual true false "the FCS read-off parses its binding")

    (match FSharpAbstraction.parseReadOff readOffJson with
     | Ok readOff ->
         match FSharpAbstraction.fromReadOff "1" "sha256:demo" readOff Map.empty with
         | Ok abstraction ->
             match FSharpAbstraction.classify abstraction None with
             | Ok result ->
                 assertEqual
                     (Some PackageLogic.RecursiveFunction)
                     (result.Bindings
                      |> List.tryFind (fun item -> item.Name = "f")
                      |> Option.map (fun item -> item.Kind))
                     "the FCS read-off lowers to a recursive classification"
             | Error _ -> assertEqual true false "the FCS read-off lowers to a recursive classification"
         | Error _ -> assertEqual true false "the FCS read-off lowers to a recursive classification"
     | Error _ -> assertEqual true false "the FCS read-off lowers to a recursive classification")

    (match FSharpAbstraction.parseReadOff readOffWithoutBodyJson with
     | Ok readOff ->
         match FSharpAbstraction.fromReadOff "1" "sha256:demo" readOff Map.empty with
         | Error errors ->
             assertEqual
                 true
                 (errors
                  |> List.exists (function
                      | FSharpAbstraction.MissingBody "f" -> true
                      | _ -> false))
                 "a read-off binding without a translated body is refused"
         | Ok _ -> assertEqual true false "a read-off binding without a translated body is refused"
     | Error _ -> assertEqual true false "a read-off binding without a translated body is refused")

    (match FSharpAbstraction.classify abstraction None with
     | Ok result ->
         let metadata = FSharpAbstraction.metadata result.Bindings
         let encoded = ClassificationWire.encode metadata

         (match ClassificationWire.decode encoded with
          | Ok decoded -> assertEqual metadata decoded "IPC classification metadata round-trips"
          | Error _ -> assertEqual true false "IPC classification metadata round-trips")
     | Error _ -> assertEqual true false "IPC classification metadata round-trips")

    let metadataWithBody =
        """{ "schemaVersion": 1, "bindings": [ { "name": "f", "kind": "recursive-function", "version": 1, "body": {} } ] }"""

    (match ClassificationWire.decode metadataWithBody with
     | Error ClassificationWire.BodyNotAllowed -> assertEqual true true "IPC classification metadata refuses a body"
     | _ -> assertEqual true false "IPC classification metadata refuses a body")

    let metadataWithWrongVersion =
        """{ "schemaVersion": 1, "bindings": [ { "name": "f", "kind": "recursive-function", "version": 2 } ] }"""

    (match ClassificationWire.decode metadataWithWrongVersion with
     | Error(ClassificationWire.MetadataVersionMismatch _) ->
         assertEqual true true "IPC classification metadata refuses a version skew"
     | _ -> assertEqual true false "IPC classification metadata refuses a version skew")

    let referencesFcs =
        typeof<FSharpAbstraction.FSharpAbstraction>.Assembly.GetReferencedAssemblies()
        |> Array.exists (fun assembly -> assembly.Name = "FSharp.Compiler.Service")

    assertEqual false referencesFcs "the runtime abstraction does not reference FCS"

    let skewedAbstraction = { abstraction with SchemaVersion = 2 }

    (match FSharpAbstraction.classify skewedAbstraction None with
     | Error errors ->
         assertEqual
             true
             (errors
              |> List.exists (function
                  | FSharpAbstraction.AbstractionSchemaMismatch 2 -> true
                  | _ -> false))
             "an F# abstraction schema skew is refused"
     | Ok _ -> assertEqual true false "an F# abstraction schema skew is refused")

    printfn "Row and set types:"

    let rowClosed =
        match RowTypes.ofList [ "x"; "y" ] with
        | Ok row -> row
        | Error _ -> failwith "row test setup"

    (match RowTypes.unify "row" rowClosed rowClosed RowTypes.emptySubstitution 0 with
     | Ok(substitution, _) ->
         assertEqual true (Map.isEmpty substitution) "closed rows with the same labels unify"
     | Error _ -> assertEqual true false "closed rows with the same labels unify")

    let rowOther =
        match RowTypes.ofList [ "x"; "z" ] with
        | Ok row -> row
        | Error _ -> failwith "row test setup"

    (match RowTypes.unify "row" rowClosed rowOther RowTypes.emptySubstitution 0 with
     | Error(RowTypes.Mismatch _) -> assertEqual true true "closed rows with different labels are refused"
     | _ -> assertEqual true false "closed rows with different labels are refused")

    let rowOpen = RowTypes.Extend("x", RowTypes.Variable(RowTypes.RowVariable 0))

    (match RowTypes.unify "row" rowOpen rowClosed RowTypes.emptySubstitution 1 with
     | Ok(substitution, _) ->
         match Map.tryFind (RowTypes.RowVariable 0) substitution with
         | Some bound ->
             assertEqual [ "y" ] (RowTypes.labelsOf bound) "an open row absorbs the other side's labels"
         | None -> assertEqual true false "an open row absorbs the other side's labels"
     | Error _ -> assertEqual true false "an open row absorbs the other side's labels")

    let rowOpenOther = RowTypes.Extend("z", RowTypes.Variable(RowTypes.RowVariable 1))

    (match RowTypes.unify "row" rowOpen rowOpenOther RowTypes.emptySubstitution 2 with
     | Ok(substitution, next) ->
         assertEqual 3 next "two open rows allocate one fresh tail"

         match
             Map.tryFind (RowTypes.RowVariable 0) substitution,
             Map.tryFind (RowTypes.RowVariable 1) substitution
         with
         | Some leftBound, Some rightBound ->
             assertEqual
                 (RowTypes.labelsOf leftBound @ RowTypes.labelsOf rightBound |> Set.ofList)
                 (Set.ofList [ "z"; "x" ])
                 "two open rows meet at a common tail"
         | _ -> assertEqual true false "two open rows meet at a common tail"
     | Error _ -> assertEqual true false "two open rows meet at a common tail")

    (match
        RowTypes.unify
            "row"
            (RowTypes.Variable(RowTypes.RowVariable 0))
            (RowTypes.Extend("x", RowTypes.Variable(RowTypes.RowVariable 0)))
            RowTypes.emptySubstitution
            1
     with
     | Error(RowTypes.OccursCheck _) -> assertEqual true true "a row variable cannot occur in itself"
     | _ -> assertEqual true false "a row variable cannot occur in itself")

    let lackingRow =
        RowTypes.Variable(RowTypes.RowVariable 0)

    let lacksX =
        Map.ofList [ RowTypes.RowVariable 0, Set.singleton "x" ]

    (match
        RowTypes.unifyWithLacks
            "row"
            lackingRow
            (RowTypes.Extend("x", RowTypes.Empty))
            RowTypes.emptySubstitution
            lacksX
            1
     with
     | Error(RowTypes.LacksViolation _) -> assertEqual true true "a row variable cannot absorb a label it lacks"
     | _ -> assertEqual true false "a row variable cannot absorb a label it lacks")

    let lacksZ =
        Map.ofList [ RowTypes.RowVariable 0, Set.singleton "z" ]

    (match
        RowTypes.unifyWithLacks
            "row"
            (RowTypes.Extend("y", lackingRow))
            (RowTypes.Extend("y", RowTypes.Extend("x", RowTypes.Empty)))
            RowTypes.emptySubstitution
            lacksZ
            1
     with
     | Ok(substitution, _, _) ->
         assertEqual
             [ "x" ]
             (Map.tryFind (RowTypes.RowVariable 0) substitution
              |> Option.map RowTypes.labelsOf
              |> Option.defaultValue [])
             "a row variable absorbs a label it does not lack"
     | Error _ -> assertEqual true false "a row variable absorbs a label it does not lack")

    let lackedField: TypeRetrieval.RecordField =
        { Name = "x"; Type = TypeRetrieval.Primitive "number" }

    let allowedField: TypeRetrieval.RecordField =
        { Name = "y"; Type = TypeRetrieval.Primitive "text" }

    let rowVariable = RowTypes.RowVariable 0

    let lackedState =
        { TypeRetrieval.emptyInferenceState with
            RecordLacks = Map.ofList [ rowVariable, Set.singleton lackedField ]
        }

    (match
        TypeRetrieval.unifyState
            lackedState
            (TypeRetrieval.Record(RowTypes.Variable rowVariable))
            (TypeRetrieval.Record(RowTypes.Extend(lackedField, RowTypes.Empty)))
     with
     | Error(TypeRetrieval.RowLacksViolation _) ->
         assertEqual true true "the host record unifier refuses a lacked field"
     | _ -> assertEqual true false "the host record unifier refuses a lacked field")

    let allowedState =
        { TypeRetrieval.emptyInferenceState with
            RecordLacks = Map.ofList [ rowVariable, Set.singleton allowedField ]
        }

    (match
        TypeRetrieval.unifyState
            allowedState
            (TypeRetrieval.Record(RowTypes.Variable rowVariable))
            (TypeRetrieval.Record(RowTypes.Extend(lackedField, RowTypes.Empty)))
     with
     | Ok next ->
         assertEqual
             (Some(RowTypes.Extend(lackedField, RowTypes.Empty)))
             (Map.tryFind rowVariable next.RecordRows)
             "the host record unifier absorbs a field it does not lack"
     | Error _ -> assertEqual true false "the host record unifier absorbs a field it does not lack")

    (match
        TypeRetrieval.projectField
            lackedState
            "x"
            (TypeRetrieval.Record(RowTypes.Variable rowVariable))
     with
     | Error(TypeRetrieval.RowLacksViolation _) ->
         assertEqual true true "field access refuses a lacked field"
     | _ -> assertEqual true false "field access refuses a lacked field")

    let setClosed = LabelSets.closed (Set.ofList [ 1; 2 ])

    (match LabelSets.unify "set" setClosed setClosed Map.empty 0 with
     | Ok(substitution, _) ->
         assertEqual true (Map.isEmpty substitution) "closed sets with the same labels unify"
     | Error _ -> assertEqual true false "closed sets with the same labels unify")

    let setOther = LabelSets.closed (Set.ofList [ 1; 3 ])

    (match LabelSets.unify "set" setClosed setOther Map.empty 0 with
     | Error(LabelSets.Mismatch _) -> assertEqual true true "closed sets with different labels are refused"
     | _ -> assertEqual true false "closed sets with different labels are refused")

    let setOpen =
        LabelSets.Open(Set.singleton 1, LabelSets.SetVariable 0)

    (match LabelSets.unify "set" setOpen setClosed Map.empty 1 with
     | Ok(substitution, _) ->
         match Map.tryFind (LabelSets.SetVariable 0) substitution with
         | Some bound ->
             assertEqual (Set.ofList [ 2 ]) (LabelSets.known bound) "an open set absorbs the other side's labels"
         | None -> assertEqual true false "an open set absorbs the other side's labels"
     | Error _ -> assertEqual true false "an open set absorbs the other side's labels")

    let setOpenOther =
        LabelSets.Open(Set.singleton 3, LabelSets.SetVariable 1)

    (match LabelSets.unify "set" setOpen setOpenOther Map.empty 2 with
     | Ok(substitution, next) ->
         assertEqual 3 next "two open sets allocate one fresh unknown"

         match
             Map.tryFind (LabelSets.SetVariable 0) substitution,
             Map.tryFind (LabelSets.SetVariable 1) substitution
         with
         | Some leftBound, Some rightBound ->
             assertEqual
                 (Set.union (LabelSets.known leftBound) (LabelSets.known rightBound))
                 (Set.ofList [ 1; 3 ])
                 "two open sets meet at a common unknown"
         | _ -> assertEqual true false "two open sets meet at a common unknown"
     | Error _ -> assertEqual true false "two open sets meet at a common unknown")

    let setVariable = LabelSets.SetVariable 0

    let setLacks =
        Map.ofList [ setVariable, Set.singleton 1 ]

    (match
        LabelSets.unifyWithLacks
            "set"
            (LabelSets.Open(Set.empty, setVariable))
            (LabelSets.closed (Set.singleton 1))
            Map.empty
            setLacks
            1
     with
     | Error(LabelSets.LacksViolation _) -> assertEqual true true "a set variable cannot absorb a label it lacks"
     | _ -> assertEqual true false "a set variable cannot absorb a label it lacks")

    (match
        LabelSets.unifyWithLacks
            "set"
            (LabelSets.Open(Set.empty, setVariable))
            (LabelSets.closed (Set.singleton 2))
            Map.empty
            setLacks
            1
     with
     | Ok(substitution, _, _) ->
         assertEqual
             (Some(LabelSets.closed (Set.singleton 2)))
             (Map.tryFind setVariable substitution)
             "a set variable absorbs a label it does not lack"
     | Error _ -> assertEqual true false "a set variable absorbs a label it does not lack")

    (match
        LabelSets.subtractOpen
            (Set.singleton 1)
            (LabelSets.Open(Set.singleton 1, setVariable))
            LabelSets.emptyLacks
     with
     | Ok(set, lacks) ->
         assertEqual
             (Some(Set.singleton 1))
             (Map.tryFind setVariable lacks)
             "open subtraction adds a lacks constraint"
         assertEqual (Set.empty) (LabelSets.known set) "open subtraction removes the known label"
     | Error _ -> assertEqual true false "open subtraction adds a lacks constraint")

    let effectLacksState =
        { TypeRetrieval.emptyUnification with
            EffectLacks = Map.ofList [ LabelSets.SetVariable 0, Set.singleton "io" ]
        }

    (match
        TypeRetrieval.unifyEffectSets
            "effects"
            (LabelSets.Open(Set.empty, LabelSets.SetVariable 0))
            (LabelSets.closed (Set.singleton "io"))
            effectLacksState
     with
     | Error(TypeRetrieval.EffectLacksViolation _) ->
         assertEqual true true "the host effect unifier refuses a lacked effect"
     | _ -> assertEqual true false "the host effect unifier refuses a lacked effect")

    (match
        TypeRetrieval.subtractEffectWithLacks
            "io"
            (LabelSets.Open(Set.singleton "io", LabelSets.SetVariable 0))
            LabelSets.emptyLacks
     with
     | Ok(set, lacks) ->
         assertEqual
             (Some(Set.singleton "io"))
             (Map.tryFind (LabelSets.SetVariable 0) lacks)
             "the host open effect subtraction records a lacks constraint"
         assertEqual (Set.empty) (LabelSets.known set) "the host open effect subtraction removes the label"
     | Error _ -> assertEqual true false "the host open effect subtraction records a lacks constraint")

    let recordState =
        { TypeRetrieval.emptyInferenceState with
            Shapes = Map.ofList [ "point", [ "x"; "y" ] ]
        }

    let hostRecord fields =
        match RecordTypes.ofList fields with
        | Ok row -> TypeRetrieval.Record row
        | Error reason -> failwith reason

    (match
        TypeRetrieval.infer
            []
            recordState
            Map.empty
            (Message("point", [ Literal(NumberLiteral 1.0); Literal(NumberLiteral 2.0) ]))
     with
     | Ok(inferred, _) ->
         assertEqual
             (hostRecord
                 [
                     "x", TypeRetrieval.Primitive "number"
                     "y", TypeRetrieval.Primitive "number"
                 ])
             inferred.Type
             "a shape message infers a closed record"
     | Error _ -> assertEqual true false "a shape message infers a closed record")

    let pointRecord =
        hostRecord
            [
                "x", TypeRetrieval.Primitive "number"
                "y", TypeRetrieval.Primitive "number"
            ]

    let pointRecordOther =
        hostRecord
            [
                "x", TypeRetrieval.Primitive "number"
                "y", TypeRetrieval.Primitive "text"
            ]

    let circleRecord =
        hostRecord [ "x", TypeRetrieval.Primitive "number" ]

    (match TypeRetrieval.unify pointRecord pointRecord Map.empty with
     | Ok _ -> assertEqual true true "records with the same fields unify"
     | Error _ -> assertEqual true false "records with the same fields unify")

    (match TypeRetrieval.unify pointRecord circleRecord Map.empty with
     | Error(TypeRetrieval.TypeMismatch _) -> assertEqual true true "records with different fields are refused"
     | _ -> assertEqual true false "records with different fields are refused")

    (match TypeRetrieval.unify pointRecord pointRecordOther Map.empty with
     | Error(TypeRetrieval.TypeMismatch _) ->
         assertEqual true true "records with different field types are refused"
     | _ -> assertEqual true false "records with different field types are refused")

    let openPointRecord =
        TypeRetrieval.Record(
            RowTypes.Extend(
                { Name = "x"; Type = TypeRetrieval.Primitive "number" },
                RowTypes.Variable(RowTypes.RowVariable 0)
            )
        )

    (match TypeRetrieval.unifyWith openPointRecord pointRecord TypeRetrieval.emptyUnification with
     | Ok state ->
         match Map.tryFind (RowTypes.RowVariable 0) state.RecordRows with
         | Some row ->
             assertEqual
                 [ "y" ]
                 (TypeRetrieval.recordFields row |> List.map (fun field -> field.Name))
                 "the host open record absorbs a field with its payload"
         | None -> assertEqual true false "the host open record absorbs a field with its payload"
     | Error _ -> assertEqual true false "the host open record absorbs a field with its payload")

    let openPointRecordOther =
        TypeRetrieval.Record(
            RowTypes.Extend(
                { Name = "x"; Type = TypeRetrieval.Primitive "text" },
                RowTypes.Variable(RowTypes.RowVariable 1)
            )
        )

    (match
        TypeRetrieval.unifyWith
            openPointRecordOther
            pointRecord
            TypeRetrieval.emptyUnification
     with
     | Error(TypeRetrieval.TypeMismatch _) ->
         assertEqual true true "the host open record unifies a common field's payload"
     | _ -> assertEqual true false "the host open record unifies a common field's payload")

    let recordTerm fields =
        match Unification.recordOfList fields with
        | Ok row -> Unification.Record row
        | Error _ -> failwith "record setup"

    let modelRecord =
        recordTerm
            [
                "x", Unification.Primitive "number"
                "y", Unification.Primitive "number"
            ]

    (match Unification.unifyType modelRecord modelRecord Unification.emptyState with
     | Ok _ -> assertEqual true true "the kinded model unifies a closed record"
     | Error _ -> assertEqual true false "the kinded model unifies a closed record")

    let modelRecordOther =
        recordTerm
            [
                "x", Unification.Primitive "number"
                "y", Unification.Primitive "text"
            ]

    (match Unification.unifyType modelRecord modelRecordOther Unification.emptyState with
     | Error(Unification.TypeMismatch _) ->
         assertEqual true true "the kinded model refuses a record payload mismatch"
     | _ -> assertEqual true false "the kinded model refuses a record payload mismatch")

    let openModelRecord =
        Unification.Record(
            RowTypes.Extend(
                { Name = "x"; Type = Unification.Primitive "number" },
                RowTypes.Variable(RowTypes.RowVariable 0)
            )
        )

    let closedModelRecord =
        recordTerm
            [
                "x", Unification.Primitive "number"
                "y", Unification.Primitive "text"
            ]

    (match Unification.unifyType openModelRecord closedModelRecord Unification.emptyState with
     | Ok state ->
         match Map.tryFind (RowTypes.RowVariable 0) state.RecordRows with
         | Some row ->
             assertEqual
                 [ "y" ]
                 (Unification.recordFields row |> List.map (fun field -> field.Name))
                 "an open record absorbs a field with its payload"
         | None -> assertEqual true false "an open record absorbs a field with its payload"
     | Error _ -> assertEqual true false "an open record absorbs a field with its payload")

    let openModelRecordOther =
        Unification.Record(
            RowTypes.Extend(
                { Name = "x"; Type = Unification.Primitive "text" },
                RowTypes.Variable(RowTypes.RowVariable 1)
            )
        )

    (match Unification.unifyType openModelRecordOther closedModelRecord Unification.emptyState with
     | Error(Unification.TypeMismatch _) ->
         assertEqual true true "an open record unifies a common field's payload"
     | _ -> assertEqual true false "an open record unifies a common field's payload")

    let openRecordScheme = Unification.generalize Set.empty Set.empty openModelRecord

    assertEqual
        [ RowTypes.RowVariable 0 ]
        openRecordScheme.QuantifiedRows
        "a scheme quantifies a free record row variable"

    let instantiatedRecord, _, _ = Unification.instantiate (0, 0) openRecordScheme

    (match instantiatedRecord with
     | Unification.Record row ->
         match Unification.recordTail row with
         | RowTypes.Variable(RowTypes.RowVariable variable) ->
             assertEqual 1 variable "instantiation freshens a record row variable"
         | _ -> assertEqual true false "instantiation freshens a record row variable"
     | _ -> assertEqual true false "instantiation freshens a record row variable")

    let openEffects =
        LabelSets.Open(Set.empty, LabelSets.SetVariable 0)

    let openFunction =
        Unification.Function([ Unification.Primitive "number" ], Unification.Primitive "number", openEffects)

    let lacksScheme =
        Unification.generalizeWithLacks
            Set.empty
            Set.empty
            Set.empty
            (Map.ofList [ LabelSets.SetVariable 0, Set.singleton "io" ])
            RowTypes.emptyLacks
            openFunction

    let _, instantiatedLacks, _, _, _ =
        Unification.instantiateWithLacks (0, 7) lacksScheme

    assertEqual
        (Some(Set.singleton "io"), Some(Set.singleton "io"))
        (Map.tryFind (LabelSets.SetVariable 0) lacksScheme.SetLacks,
         Map.tryFind (LabelSets.SetVariable 7) instantiatedLacks)
        "the reference scheme retains and restores a set lacks constraint"

    let closedFunction =
        Unification.Function(
            [ Unification.Primitive "number" ],
            Unification.Primitive "number",
            LabelSets.Closed(Set.singleton "io")
        )

    (match Unification.unifyType openFunction closedFunction Unification.emptyState with
     | Ok state ->
         match Unification.applyType state openFunction with
         | Unification.Function(_, _, effects) ->
             assertEqual
                 (LabelSets.Closed(Set.singleton "io"))
                 effects
                 "an open effect set binds to concrete effects"
         | _ -> assertEqual true false "an open effect set binds to concrete effects"
     | Error _ -> assertEqual true false "an open effect set binds to concrete effects")

    let openSetOne = LabelSets.Open(Set.singleton "io", LabelSets.SetVariable 1)
    let openSetTwo = LabelSets.Open(Set.singleton "net", LabelSets.SetVariable 2)

    (match Unification.unifySet "effects" openSetOne openSetTwo Unification.emptyState with
     | Ok state -> assertEqual 1 state.NextSet "two open effect sets meet at a fresh unknown"
     | Error _ -> assertEqual true false "two open effect sets meet at a fresh unknown")

    (match
        Unification.unifyKinded
            (Unification.RowTerm RowTypes.Empty)
            (Unification.SetTerm(LabelSets.Closed(Set.singleton "io")))
            Unification.emptyState
     with
     | Error(Unification.KindMismatch _) -> assertEqual true true "a row and a set are refused by kind"
     | _ -> assertEqual true false "a row and a set are refused by kind")

    let modelScheme = Unification.generalize Set.empty Set.empty openFunction
    assertEqual [ LabelSets.SetVariable 0 ] modelScheme.QuantifiedSets "a scheme quantifies a free set variable"

    let _, _, nextSet = Unification.instantiate (0, 1) modelScheme
    assertEqual 2 nextSet "instantiating a scheme freshens the set variable"

    let adapterRecord =
        hostRecord [ "x", TypeRetrieval.Primitive "number" ]

    assertEqual true (UnificationHost.agrees adapterRecord adapterRecord) "the host adapter agrees on a closed record"

    let adapterCode =
        TypeRetrieval.Code(TypeRetrieval.Primitive "number", TypeRetrieval.effectSet "io")

    (match UnificationHost.toType (UnificationHost.ofType adapterCode) with
     | Ok converted ->
         assertEqual
             true
             (converted = adapterCode)
             "a code type survives the host/reference bridge"
     | Error reason ->
         assertEqual "ok" reason "a code type must convert through the host/reference bridge")

    assertEqual true (UnificationHost.agrees adapterCode adapterCode) "the host adapter agrees on a code type"

    let unificationSource =
        System.IO.File.ReadAllText(
            System.IO.Path.Combine(__SOURCE_DIRECTORY__, "fixtures", "unification.book")
        )

    let unificationPath = markerPath unificationSource

    let checkUnification (word: string) (expected: float) =
        match BookRunner.cast shellState0 unificationPath (Some word) [] with
        | Ok final ->
            match Stack.popResolved final.Store final.Stack with
            | Some(tensor, _) ->
                assertEqual expected (Tensor.item tensor 0) ("the self-hosted unifier returns " + word)
            | None -> assertEqual true false ("the self-hosted unifier returns " + word)
        | Error reason -> assertEqual "ok" reason ("the self-hosted unifier returns " + word)

    [
        ("caseprimok", 1.0)
        ("caseprimno", 0.0)
        ("casetvar", 1.0)
        ("caseoccurs", 0.0)
        ("casefn", 1.0)
        ("caseeffect", 1.0)
        ("caserecord", 1.0)
        ("caserecordno", 0.0)
        ("caserow", 1.0)
        ("caserowopen", 1.0)
        ("casesetopen", 1.0)
        ("casesets", 1.0)
        ("casesetsnext", 3.0)
        ("casekind", 0.0)
    ]
    |> List.iter (fun (word, expected) -> checkUnification word expected)

    System.IO.File.Delete unificationPath

    let fieldBookPath =
        markerPath
            """shape point with x y.
logic xof p = field("x" p).
logic yof p = field("y" p).
logic main = add(xof(point(1 2)) yof(point(3 4))).
"""

    (match BookRunner.check shellState0 fieldBookPath with
     | Ok() -> assertEqual true true "a book with field access passes the check gate"
     | Error reason -> assertEqual "ok" reason "a book with field access passes the check gate")

    let fieldBookState =
        { shellState0 with
            Capabilities = Set.add "book" shellState0.Capabilities
        }

    (match BookRunner.cast fieldBookState fieldBookPath (Some "main") [] with
     | Ok final ->
         match Stack.popResolved final.Store final.Stack with
         | Some(tensor, _) -> assertEqual 5.0 (Tensor.item tensor 0) "field access reads named record fields"
         | None -> assertEqual true false "field access reads named record fields"
     | Error reason -> assertEqual "ok" reason "field access reads named record fields")

    System.IO.File.Delete fieldBookPath

    let inventoryPath =
        System.IO.Path.Combine(__SOURCE_DIRECTORY__, "fixtures", "inventory.book")

    (match BookRunner.check shellState0 inventoryPath with
     | Ok() -> assertEqual true true "the inventory case study checks"
     | Error reason -> assertEqual "ok" reason "the inventory case study checks")

    (match BookRunner.cast fieldBookState inventoryPath (Some "main") [] with
     | Ok final ->
         match Stack.popResolved final.Store final.Stack with
         | Some(tensor, _) ->
             assertEqual 6.0 (Tensor.item tensor 0) "the inventory case study computes the total"
         | None -> assertEqual true false "the inventory case study computes the total"
     | Error reason -> assertEqual "ok" reason "the inventory case study computes the total")

    let effectFieldBookPath =
        markerPath
            """shape box with f.
logic make = box(run).
logic apply f = f("pkg" "fn").
logic main = apply(field("f" make)).
"""

    (match BookRunner.check shellState0 effectFieldBookPath with
     | Ok() -> assertEqual true true "a book with an effectful function field checks"
     | Error reason -> assertEqual "ok" reason "a book with an effectful function field checks")

    System.IO.File.Delete effectFieldBookPath

    runTypeRetrievalTests ()

    printfn "Ownership of inputs and effect boundaries:"

    let tensorData = [| 1.0; 2.0 |]
    let tensorShape = [| 2 |]

    let tensor =
        match Tensor.create tensorShape tensorData with
        | Ok value -> value
        | Error reason -> failwith reason

    tensorData.[0] <- 99.0
    tensorShape.[0] <- 99

    assertEqual 1.0 (Tensor.item tensor 0) "a tensor copies its input data"
    assertEqual 2 (Tensor.size tensor) "a tensor copies its input shape"

    let shellRoot =
        System.IO.Path.Combine(
            System.IO.Path.GetTempPath(),
            "scale-shell-root-" + System.Guid.NewGuid().ToString("N")
        )

    let shellOutside =
        System.IO.Path.Combine(
            System.IO.Path.GetTempPath(),
            "scale-shell-outside-" + System.Guid.NewGuid().ToString("N")
        )

    System.IO.Directory.CreateDirectory shellRoot |> ignore
    System.IO.Directory.CreateDirectory shellOutside |> ignore
    let shellLink = System.IO.Path.Combine(shellRoot, "escape")

    (try
        System.IO.File.CreateSymbolicLink(shellLink, shellOutside) |> ignore

        let restrictedShell =
            ShellHost.ProcessShell(
                ShellHost.ShellPolicy.Restricted(Set.ofList [ "echo" ], [ shellRoot ], true)
            )
            :> ShellHost.ShellProcess

        match restrictedShell.CheckWritePath(System.IO.Path.Combine(shellLink, "file.txt")) with
        | Error _ -> assertEqual true true "a symlink cannot escape a write root"
        | Ok () -> assertEqual true false "a symlink cannot escape a write root"
     with error ->
         assertEqual "ok" error.Message "a symlink cannot escape a write root")

    System.IO.Directory.Delete(shellRoot, true)
    System.IO.Directory.Delete(shellOutside, true)

    let timeoutShell =
        ShellHost.ProcessShell(ShellHost.Unrestricted, Some 50) :> ShellHost.ShellProcess

    (match timeoutShell.Run("sleep", [ "5" ]) with
     | Error reason -> assertEqual true (reason.Contains "timed out") "a shell command times out"
     | Ok _ -> assertEqual true false "a shell command times out")

    printfn "Declarative IO:"

    let installText =
        """install photos {
  resource files : directory at "photos" recursive true follow-links false hidden false
  resource trash : trash at "photos/.trash"
  resource vision : vision at "aesthetic-v1" threshold 0.85
  default delete trash
  default all recursive true follow-links false hidden false
  default undecided skip
  default confirmation required
}"""

    let installation =
        match DeclarativeIo.parse installText with
        | Ok parsed -> parsed
        | Error error -> failwith ("install parser setup: " + string error)

    assertEqual "photos" installation.Name "an install file parses its installation name"
    assertEqual 3 installation.Capabilities.Count "an install file parses its capabilities"

    let candidate
        (path: string)
        (kind: DeclarativeIo.FileKind)
        (verdict: DeclarativeIo.Verdict)
        : DeclarativeIo.Candidate =
        {
            Path = path
            Hash = path
            Kind = kind
            Verdict = verdict
            Evidence =
                {
                    ModelId = "aesthetic-v1"
                    ModelVersion = "1.0"
                    Score = 0.9
                    ContentHash = path
                }
        }

    let candidates =
        [
            candidate "photos/a.png" DeclarativeIo.RegularFile DeclarativeIo.NotPretty
            candidate "photos/b.png" DeclarativeIo.RegularFile DeclarativeIo.Pretty
            candidate "photos/c.txt" DeclarativeIo.RegularFile (DeclarativeIo.NotApplicable "not an image")
            candidate "photos/d.png" DeclarativeIo.RegularFile (DeclarativeIo.Undecided "low confidence")
            candidate "photos/sub/e.png" DeclarativeIo.RegularFile DeclarativeIo.NotPretty
            candidate "photos/.hidden.png" DeclarativeIo.RegularFile DeclarativeIo.NotPretty
            candidate "photos/link.png" DeclarativeIo.SymbolicLink DeclarativeIo.NotPretty
            candidate "photos/../outside.png" DeclarativeIo.RegularFile DeclarativeIo.NotPretty
            candidate "elsewhere/f.png" DeclarativeIo.RegularFile DeclarativeIo.NotPretty
        ]

    let removeIntent =
        DeclarativeIo.Remove(
            DeclarativeIo.CapabilityName.create "files",
            None,
            DeclarativeIo.NotPrettyPredicate
        )

    let plan =
        match DeclarativeIo.planRemove installation removeIntent candidates with
        | Ok planned -> planned
        | Error error -> failwith ("declarative plan setup: " + string error)

    let actions = plan.Items |> List.map (fun item -> item.Action)
    let trashCount =
        actions
        |> List.filter (function
            | DeclarativeIo.MoveToTrash _ -> true
            | _ -> false)
        |> List.length

    assertEqual 2 trashCount "a plan selects only not-pretty regular files"
    assertEqual false (plan.Items |> List.exists (fun item -> item.Path = "elsewhere/f.png")) "a plan stays inside the installed scope"
    assertEqual false (plan.Items |> List.exists (fun item -> item.Path = "photos/../outside.png")) "a plan refuses path traversal"
    assertEqual true (plan.Items |> List.exists (fun item -> item.Path = "photos/.hidden.png" && item.Action = DeclarativeIo.Skip "hidden file")) "a plan skips hidden files by default"
    assertEqual 1 plan.Undecided "a plan counts undecided verdicts"
    assertEqual 1 plan.NotApplicable "a plan counts non-image files"
    assertEqual DeclarativeIo.ConfirmationRequired plan.Confirmation "a plan carries the confirmation policy"

    let visionlessInstallation =
        {
            installation with
                Capabilities =
                    installation.Capabilities
                    |> Map.filter (fun _ capability ->
                        match capability with
                        | DeclarativeIo.Vision _ -> false
                        | _ -> true)
        }

    let wrongModelCandidate =
        let original =
            candidate "photos/wrong.png" DeclarativeIo.RegularFile DeclarativeIo.NotPretty

        { original with Evidence = { original.Evidence with ModelId = "other-model" } }

    let visionlessRefused =
        match DeclarativeIo.planRemove visionlessInstallation removeIntent candidates with
        | Error DeclarativeIo.MissingVisionCapability -> true
        | _ -> false

    let wrongModelRefused =
        match DeclarativeIo.planRemove installation removeIntent [ wrongModelCandidate ] with
        | Error(DeclarativeIo.InvalidVerdictEvidence _) -> true
        | _ -> false

    assertEqual true (visionlessRefused && wrongModelRefused) "a plan requires a configured matching vision model"

    let directoryCapability
        (recursive: bool option)
        (followLinks: bool option)
        (hidden: bool option)
        : DeclarativeIo.Capability =
        DeclarativeIo.Directory
            {
                Path = "photos"
                Recursive = recursive
                FollowLinks = followLinks
                Hidden = hidden
            }

    let followInstallation =
        {
            installation with
                Capabilities =
                    installation.Capabilities
                    |> Map.add
                        (DeclarativeIo.CapabilityName.create "files")
                        (directoryCapability (Some true) (Some true) (Some false))
        }

    let followPlan =
        match DeclarativeIo.planRemove followInstallation removeIntent candidates with
        | Ok planned -> planned
        | Error error -> failwith ("follow-links plan setup: " + string error)

    let followAllowed =
        followPlan.Items
        |> List.exists (fun item ->
            item.Path = "photos/link.png"
            && match item.Action with
               | DeclarativeIo.MoveToTrash _ -> true
               | _ -> false)

    let defaultInstallation =
        {
            installation with
                Capabilities =
                    installation.Capabilities
                    |> Map.add
                        (DeclarativeIo.CapabilityName.create "files")
                        (directoryCapability None None None)
                Policy =
                    {
                        installation.Policy with
                            All =
                                {
                                    Recursive = false
                                    FollowLinks = false
                                    Hidden = false
                                }
                    }
        }

    let defaultPlan =
        match DeclarativeIo.planRemove defaultInstallation removeIntent candidates with
        | Ok planned -> planned
        | Error error -> failwith ("default-all plan setup: " + string error)

    let defaultHonored =
        defaultPlan.Items
        |> List.exists (fun item ->
            item.Path = "photos/sub/e.png"
            && item.Action = DeclarativeIo.Skip "not recursive")

    assertEqual true (followAllowed && defaultHonored) "directory overrides fall back to the default-all policy"

    let refusingInstallation =
        {
            installation with
                Policy =
                    {
                        installation.Policy with
                            Undecided = DeclarativeIo.RefuseUndecided
                    }
        }

    (match DeclarativeIo.planRemove refusingInstallation removeIntent candidates with
     | Error(DeclarativeIo.UndecidedVerdict _) -> assertEqual true true "a refusing policy refuses an undecided verdict"
     | _ -> assertEqual true false "a refusing policy refuses an undecided verdict")

    (match
        DeclarativeIo.planRemove
            installation
            (DeclarativeIo.Remove(
                DeclarativeIo.CapabilityName.create "vision",
                None,
                DeclarativeIo.NotPrettyPredicate
            ))
            candidates
     with
     | Error(DeclarativeIo.WrongCapabilityKind _) -> assertEqual true true "a plan refuses a non-directory scope"
     | _ -> assertEqual true false "a plan refuses a non-directory scope")

    let executed = ResizeArray<string>()

    let executor =
        { new DeclarativeIo.IPlanExecutor with
            member _.Hash path = Ok path
            member _.Apply item =
                executed.Add item.Path
                Ok() }

    let confirmation =
        DeclarativeIo.ConfirmationReceipt.create (DeclarativeIo.planFingerprint plan)

    let report =
        match DeclarativeIo.apply (Some confirmation) executor plan with
        | Ok applied -> applied
        | Error error -> failwith ("declarative apply setup: " + error.Reason)

    let refusedWithoutReceipt =
        match DeclarativeIo.apply None executor plan with
        | Error error -> error.Reason.Contains("confirmation required")
        | Ok _ -> false

    let refusedWithWrongReceipt =
        let wrongConfirmation =
            DeclarativeIo.ConfirmationReceipt.create "wrong-plan"

        match DeclarativeIo.apply (Some wrongConfirmation) executor plan with
        | Error error -> error.Reason.Contains("confirmation required")
        | Ok _ -> false

    assertEqual true (refusedWithoutReceipt && refusedWithWrongReceipt) "apply requires the matching confirmation receipt"

    assertEqual 2 report.Applied.Length "apply runs only non-skip plan items"
    assertEqual 5 report.Skipped.Length "apply reports skipped plan items"
    assertEqual 2 executed.Count "apply invokes the host once per action"

    let failingExecutor =
        { new DeclarativeIo.IPlanExecutor with
            member _.Hash path = Ok path
            member _.Apply item =
                if item.Path = "photos/a.png" then
                    Error "close failed"
                else
                    Ok() }

    (match DeclarativeIo.apply (Some confirmation) failingExecutor plan with
     | Error error -> assertEqual 0 error.Applied.Length "apply stops on a host failure"
     | Ok _ -> assertEqual true false "apply stops on a host failure")

    let staleExecutor =
        { new DeclarativeIo.IPlanExecutor with
            member _.Hash _ = Ok "different"
            member _.Apply _ = Ok() }

    (match DeclarativeIo.apply (Some confirmation) staleExecutor plan with
     | Error error -> assertEqual true (error.Reason.Contains("hash mismatch")) "apply refuses a stale plan"
     | Ok _ -> assertEqual true false "apply refuses a stale plan")

    let realRoot =
        System.IO.Path.Combine(
            System.IO.Path.GetTempPath(),
            "scale-declarative-root-" + System.Guid.NewGuid().ToString("N")
        )

    let realOutside =
        System.IO.Path.Combine(
            System.IO.Path.GetTempPath(),
            "scale-declarative-outside-" + System.Guid.NewGuid().ToString("N")
        )

    System.IO.Directory.CreateDirectory realRoot |> ignore
    System.IO.Directory.CreateDirectory realOutside |> ignore
    let realLink = System.IO.Path.Combine(realRoot, "escape")

    (try
        System.IO.File.CreateSymbolicLink(realLink, realOutside) |> ignore

        let evidence: DeclarativeIo.VerdictEvidence =
            {
                ModelId = "aesthetic-v1"
                ModelVersion = "1.0"
                Score = 0.9
                ContentHash = realLink
            }

        let linkedPlan: DeclarativeIo.Plan =
            {
                Installation = "photos"
                Scope = realRoot
                Items =
                    [
                        {
                            Path = realLink
                            Hash = realLink
                            Verdict = DeclarativeIo.Pretty
                            Evidence = evidence
                            Action =
                                DeclarativeIo.MoveToTrash(
                                    DeclarativeIo.CapabilityName.create "trash"
                                )
                        }
                    ]
                Confirmation = DeclarativeIo.ConfirmationRequired
                Undecided = 0
                NotApplicable = 0
            }

        let linkedConfirmation =
            DeclarativeIo.ConfirmationReceipt.create (DeclarativeIo.planFingerprint linkedPlan)

        let realExecutor =
            { new DeclarativeIo.IPlanExecutor with
                member _.Hash _ = Ok realLink
                member _.Apply _ = Ok() }

        (match DeclarativeIo.apply (Some linkedConfirmation) realExecutor linkedPlan with
         | Error error ->
             assertEqual
                 true
                 (error.Reason.Contains("outside the scope"))
                 "apply refuses a symlink outside the scope"
         | Ok _ -> assertEqual true false "apply refuses a symlink outside the scope")
     with error ->
         assertEqual "ok" error.Message "apply refuses a symlink outside the scope")

    System.IO.Directory.Delete(realRoot, true)
    System.IO.Directory.Delete(realOutside, true)

    let executorRoot =
        System.IO.Path.Combine(
            System.IO.Path.GetTempPath(),
            "scale-executor-root-" + System.Guid.NewGuid().ToString("N")
        )

    let trashRoot = System.IO.Path.Combine(executorRoot, "trash")
    System.IO.Directory.CreateDirectory executorRoot |> ignore
    let trashedFile = System.IO.Path.Combine(executorRoot, "photo.txt")
    System.IO.File.WriteAllText(trashedFile, "photo")

    let trashExecutor =
        DeclarativeIoExecutor.FileSystemExecutor(trashRoot, false)

    let trashPlanExecutor = trashExecutor :> DeclarativeIo.IPlanExecutor

    let trashedHash =
        match trashPlanExecutor.Hash trashedFile with
        | Ok hash -> hash
        | Error reason -> failwith ("executor hash setup: " + reason)

    let trashedEvidence: DeclarativeIo.VerdictEvidence =
        {
            ModelId = "aesthetic-v1"
            ModelVersion = "1.0"
            Score = 0.9
            ContentHash = trashedHash
        }

    let trashPlan: DeclarativeIo.Plan =
        {
            Installation = "photos"
            Scope = executorRoot
            Items =
                [
                    {
                        Path = trashedFile
                        Hash = trashedHash
                        Verdict = DeclarativeIo.NotPretty
                        Evidence = trashedEvidence
                        Action =
                            DeclarativeIo.MoveToTrash(
                                DeclarativeIo.CapabilityName.create "trash"
                            )
                    }
                ]
            Confirmation = DeclarativeIo.ConfirmationRequired
            Undecided = 0
            NotApplicable = 0
        }

    (match DeclarativeIo.apply (Some(DeclarativeIo.ConfirmationReceipt.create (DeclarativeIo.planFingerprint trashPlan))) trashPlanExecutor trashPlan with
     | Ok _ ->
         assertEqual false (System.IO.File.Exists trashedFile) "the filesystem executor moves a file out of scope"
         assertEqual true (System.IO.File.Exists(System.IO.Path.Combine(trashRoot, "photo.txt"))) "the filesystem executor moves a file to trash"
     | Error error -> assertEqual "ok" error.Reason "the filesystem executor moves a file to trash")

    let unlinkFile = System.IO.Path.Combine(executorRoot, "unlink.txt")
    System.IO.File.WriteAllText(unlinkFile, "unlink")

    let unlinkHash =
        match trashPlanExecutor.Hash unlinkFile with
        | Ok hash -> hash
        | Error reason -> failwith ("executor hash setup: " + reason)

    let unlinkEvidence: DeclarativeIo.VerdictEvidence =
        {
            ModelId = "aesthetic-v1"
            ModelVersion = "1.0"
            Score = 0.9
            ContentHash = unlinkHash
        }

    let unlinkPlan: DeclarativeIo.Plan =
        {
            trashPlan with
                Items =
                    [
                        {
                            Path = unlinkFile
                            Hash = unlinkHash
                            Verdict = DeclarativeIo.NotPretty
                            Evidence = unlinkEvidence
                            Action =
                                DeclarativeIo.UnlinkFile(
                                    DeclarativeIo.CapabilityName.create "unlink"
                                )
                        }
                    ]
        }

    (match DeclarativeIo.apply (Some(DeclarativeIo.ConfirmationReceipt.create (DeclarativeIo.planFingerprint unlinkPlan))) trashPlanExecutor unlinkPlan with
     | Error error -> assertEqual true (error.Reason.Contains("disabled")) "the filesystem executor refuses unlink by default"
     | Ok _ -> assertEqual true false "the filesystem executor refuses unlink by default")

    let unlinkExecutor =
        DeclarativeIoExecutor.FileSystemExecutor(trashRoot, true)
        :> DeclarativeIo.IPlanExecutor

    (match DeclarativeIo.apply (Some(DeclarativeIo.ConfirmationReceipt.create (DeclarativeIo.planFingerprint unlinkPlan))) unlinkExecutor unlinkPlan with
     | Ok _ -> assertEqual false (System.IO.File.Exists unlinkFile) "the filesystem executor unlinks only when enabled"
     | Error error -> assertEqual "ok" error.Reason "the filesystem executor unlinks only when enabled")

    System.IO.Directory.Delete(executorRoot, true)

    let unknownResourceInstall =
        "install photos {\n  resource files : bogus at \"x\"\n}"

    (match DeclarativeIo.parse unknownResourceInstall with
     | Error(DeclarativeIo.UnknownResourceKind _) -> assertEqual true true "an install file refuses an unknown resource kind"
     | _ -> assertEqual true false "an install file refuses an unknown resource kind")

    let unclosedInstall =
        "install photos {\n  resource files : trash at \"x\"\n"

    (match DeclarativeIo.parse unclosedInstall with
     | Error DeclarativeIo.UnclosedInstallBlock -> assertEqual true true "an install file requires a closing block"
     | _ -> assertEqual true false "an install file requires a closing block")

    let worldInstallText =
        """install photos {
  resource files : directory at "photos" recursive true follow-links false hidden false
  resource trash : trash at "photos/.trash"
  default delete trash
  world image "images:kaos/latest"
  world type virtual-machine
  world cpus 4
  world memory 8192
  world disk 64
  world network "default"
}"""

    let worldInstallation =
        match DeclarativeIo.parse worldInstallText with
        | Ok parsed -> parsed
        | Error error -> failwith ("world install setup: " + string error)

    match worldInstallation.World with
    | Some world ->
        assertEqual "images:kaos/latest" world.Image "an install file parses its world image"
        assertEqual DeclarativeIo.VirtualMachine world.InstanceType "an install file parses its world type"
        assertEqual 4 world.Cpus "an install file parses its world CPU count"
        assertEqual 8192 world.MemoryMiB "an install file parses its world memory"
    | None -> assertEqual true false "an install file parses its world image"

    (match DeclarativeIo.renderIncusProfile worldInstallation with
     | Ok profile ->
         assertEqual
             true
             (profile.Contains("name: \"photos\"")
              && profile.Contains("user.scale.image: \"images:kaos/latest\"")
              && profile.Contains("user.scale.instance-type: \"virtual-machine\"")
              && profile.Contains("network: \"default\""))
             "an install file renders an Incus world profile"
     | Error _ -> assertEqual true false "an install file renders an Incus world profile")

    let missingWorldImageInstall =
        "install photos {\n  world cpus 4\n}"

    (match DeclarativeIo.parse missingWorldImageInstall with
     | Error DeclarativeIo.MissingWorldImage -> assertEqual true true "an install world requires an image"
     | _ -> assertEqual true false "an install world requires an image")

    let invalidWorldInstall =
        "install photos {\n  world image \"x\"\n  world cpus 0\n}"

    (match DeclarativeIo.parse invalidWorldInstall with
     | Error(DeclarativeIo.InvalidWorldValue _) -> assertEqual true true "an install world refuses an invalid CPU count"
     | _ -> assertEqual true false "an install world refuses an invalid CPU count")

    printfn "Host pattern boundary:"

    let portableHostPattern =
        PatternHost.Portable(PatternLogic.Constructor("some", [ PatternLogic.Wildcard ]))

    (match PatternHost.toPortable None portableHostPattern with
     | Ok(PatternLogic.Constructor("some", [ PatternLogic.Wildcard ])) ->
         assertEqual true true "a portable pattern stays portable"
     | _ -> assertEqual true false "a portable pattern stays portable")

    let hostOnlyPattern =
        PatternHost.HostOnly(
            "fsharp",
            "active-pattern",
            [ PatternHost.Portable PatternLogic.Wildcard ]
        )

    (match PatternHost.toPortable None hostOnlyPattern with
     | Error(PatternHost.HostSpecific("fsharp", "active-pattern")) ->
         assertEqual true true "a host-only pattern is refused without an elaborator"
     | _ -> assertEqual true false "a host-only pattern is refused without an elaborator")

    let hostElaborator =
        { new PatternHost.IHostPatternElaborator with
            member _.Lower _host feature children =
                Ok(PatternLogic.Constructor(feature, children)) }

    (match PatternHost.toPortable (Some hostElaborator) hostOnlyPattern with
     | Ok(PatternLogic.Constructor("active-pattern", [ PatternLogic.Wildcard ])) ->
         assertEqual true true "a host elaborator lowers a host-only pattern"
     | _ -> assertEqual true false "a host elaborator lowers a host-only pattern")

    printfn ""

    let total = passed + failed

    if total <> expectedChecks then
        failed <- failed + 1
        printfn $"  FAIL: expected {expectedChecks} checks, ran {total}"

    printfn ""
    printfn $"Tests passed: {passed}"
    printfn $"Tests failed: {failed}"
    printfn ""
